    // Home Page
    home_hero_title: "ملتزمون بتطوير الأزياء من خلال...",
    home_hero_subtitle: "دعم تصميم ذكاء السوق، ابتكار المنتجات وجدتها، ومجموعة واسعة من المنتجات المتنوعة",
    home_quote: "طريقة البدء هي التوقف عن الحديث والبدء في العمل.",
    quote_author: "- والت ديزني",
    stats_global: "التواجد العالمي",
    stats_staff: "الموظفون حول العالم",
    stats_rec: "موصى به",
    home_about_title: "من نحن",
    home_about_subtitle: "من نكون... !!",
    home_about_text: "في ApparelBD، نؤمن بأن الموضة ليست مجرد ملابس، بل هي بيان دائم التطور، وتعبير عن الهوية. سياق ثقافي للزمان والمكان، إدراك، طموح، إبداع وابتكار، وقيمة ومعتقد للفرد والمجتمع. نحن ندفع الموضة للأمام من خلال ذكاء السوق، وتحليل الاتجاهات، والتصميم المبتكر، والمصادر الأخلاقية. بدعم من ضمان الجودة القوي، والخدمات اللوجستية الموثوقة، والخدمة الاستثنائية، نهدف إلى تقديم قيمة متميزة لعملائنا.",
    home_about_quote: "يمتد التزامنا بتقدم الموضة ليشمل ذكاء السوق، وتحليل الاتجاهات، والتصميم المبتكر والبحث والتطوير.",
    home_about_section_title: "مدفوعون بالاتجاهات، مصادر أخلاقية، موثوقون وقابلون للتتبع – شريكك في تصنيع الأزياء-",
    home_about_section_text: "نحن نتعاون مع مصنعين ملتزمين بالمعايير العالمية لضمان التتبع والجودة ومراقبة العمليات. تدمج استوديوهات التصميم الخاصة بنا في لندن ودكا الإبداع العالمي مع المواهب المحلية، مع التركيز على البحث والتطوير، والمنتجات المدفوعة بالاتجاهات، وشخصيات الترخيص الشهيرة مثل ديزني وغيرها. تسلط عمليات التفتيش الميداني والدعم اللوجستي الكامل الضوء على التزامنا بالتصنيع المسؤول والمبتكر.",
    home_about_value_prop: "\"المصادر الأخلاقية، الاستدامة، التميز في التصنيع والخدمة الفائقة - تقدم قيمة مضافة للعملاء.\"",
    all_about_us_title: "كل شيء عنا",
    all_about_us_desc: "نؤمن بأن الموضة ليست مجرد ملابس، بل هي بيان دائم التطور، وتعبير عن الهوية، وسياق ثقافي للزمان والمكان، وإدراك، وطموح، وإبداع وابتكار، وقيمة ومعتقد للفرد والمجتمع.",
    home_fashion_title: "تطور الأزياء",
    home_fashion_subtitle: "حيث تبدأ الاتجاهات — تصميم الأزياء في حركة... !!",
    home_fashion_text: "انطلق في رحلة تطور الأزياء — حيث يشكل التصميم الرائد والتكنولوجيا المتطورة مستقبل الأناقة. في ApparelBD، تتحدث الموضة لغة الهويات المتغيرة، حيث يلتقي الخيال بالعلم ويمتزج التقليد بالابتكار.",
    home_fashion_quote_parallax: "\"الموضة ليست ثابتة؛ إنها شكل فني دائم التطور. للبقاء في المقدمة، يجب أن نعتنق التغيير والابتكار.\"",
