    // About Page
    about_hero_title: "من نحن",
    about_hero_sub: "من نكون",
    about_welcome: "مرحباً بكم في ApparelBD، حيث تلتقي الموضة بالنزاهة!!",
    about_intro_title: "شريك توريد عالمي موثوق، استراتيجي، مستدام وأخلاقي!!",
    about_intro_p1: "نؤمن بأن الموضة ليست مجرد ملابس، بل هي بيان دائم التطور، وتعبير عن الهوية، وسياق ثقافي للزمان والمكان، وإدراك، وطموح، وإبداع وابتكار، وقيمة ومعتقد للفرد والمجتمع. تأسست في عام 2024، نمزج الإبداع والاستدامة والتميز في التصنيع لتقديم حلول توريد عالمية مبتكرة.",
    about_intro_p2: "نحن نقود تطور الأزياء من خلال ذكاء السوق، وتحليل الاتجاهات، والتصميم المبتكر، وفئات المنتجات المتنوعة. يمتد التزامنا ليشمل التوريد الأخلاقي، والاستدامة، والمسؤولية الاجتماعية، والامتثال الدولي. مع شركاء تصنيع موثوقين، وضمان الجودة، وإنتاج الشخصيات المرخصة، والخدمات اللوجستية المتكاملة، نقدم خدمة فائقة وقيمة استثنائية للعملاء.",
    about_banner_green: "\"الارتقاء بالتوريد، تعزيز الشراكة - معاً نحقق المزيد!!\"",
