    // About - People
    about_people: "موظفونا:",
    about_people_sub: "موظفونا، قوتنا: الخبرة التي تدعمنا..!!",
    about_people_desc: "في ApparelBD، الموضة الهادفة يقودها أشخاص شغوفون. أكبر نقاط قوتنا هي فريقنا المتنوع والمتصل عالمياً - مبتكرون يدعمون كل مرحلة من مراحل دورة حياة الأزياء. من التصميم المواكب للموضة والتوريد الأخلاقي إلى تطوير المنتجات بدقة، وضمان الجودة الصارم، والخدمات اللوجستية السلسة، يقود خبراؤنا بإبداع ونزاهة والتزام بالاستدامة.",
    about_people_desc_2: "التعاون هو أساسنا. معاً، نقدم حلولاً تمزج بين الفن والأخلاق والتميز - لضمان أن كل قطعة نبتكرها تحمل هدفاً.",
    about_global_pres_title: "تواجد عالمي، رؤية محلية",
    about_global_pres_desc: "يقع مقرنا الرئيسي في دكا، ولدينا استوديوهات تصميم في دكا ولندن، ومكاتب توريد في المملكة المتحدة وألمانيا وكندا ونيوزيلندا، نمزج الاتجاهات العالمية بالخبرة الإقليمية لابتكار أزياء تتناسب محلياً وتلبي المعايير الدولية.",
    about_global_pres_desc_2: "تُترجم اتجاهات الموضة العالمية إلى منتجات مبتكرة وعالية الجودة مع اهتمام دقيق بالتفاصيل. بدعم من شبكات تصنيع وتوريد قوية، يتم تقديم أساسيات الموضة والحلول المصممة خصيصاً لتلبية احتياجات المستهلكين المتطورة.",
    role_designers: "مصممون خبراء من استوديوهات المملكة المتحدة وبنغلاديش",
    role_designers_desc: "مزج الجماليات العالمية بالإبداع المحلي.",
