    // Market Intel Page
    mi_hero_title: "ذكاء السوق والتصميم",
    mi_hero_sub: "رحلة التصميم",
    mi_fe_title: "تطور الأزياء",
    mi_fe_sub: "إعادة تعريف الأناقة في الحركة، حيث يرتدينا المستقبل !!",
    mi_fe_text: "تطور الأزياء ليس مجرد حركة — إنه تحول. عالم يرقص فيه الخيال مع العلم، وكل صورة ظلية تحكي قصة عن الغد. هنا، يتلاقى التصميم الرؤيوي، والبحث الجريء، والابتكار اللامحدود لإعادة تصور الموضة لعالم في حركة.",
    mi_lang_title: "الموضة لم تعد مجرد قماش — إنها لغة!!",
    mi_lang_p1: "انعكاس حي للهويات المتغيرة، نسيج منسوج بالقيم، حيث تتشابك الخيوط القديمة مع أشكال المستقبل.",
    mi_lang_p2: "في ApparelBD، التطور موجود في حمضنا النووي. يمزج مصممونا الأخلاق بالأناقة، والتقاليد بالتكنولوجيا، لصياغة قطع خالدة وجاهزة للمستقبل. باستخدام مواد الجيل القادم وتصميم النفايات الصفرية، نخلق حقبة جديدة حيث يلتقي الأسلوب بالاستدامة.",
    mi_lang_footer: "ذو مغزى، ساحر، مصنوع بوعي!!",
    mi_quote_1: "“ الموضة تتحرك بسرعة الفكر وتتدفق مع العقل — التطور هو جوهرها.”",
    mi_rd_title: "البحث والتطوير والابتكار",
    mi_rd_sub: "“ابتكار الأسلوب. إلهام التغيير..”",
    mi_rd_desc: "في تطور الأزياء، ندمج البحث والتطوير المتطور مع الابتكار الإبداعي لإعادة تعريف الموضة — صياغة قطع متينة وفنية من خلال أقمشة متقدمة وزخارف وتقنيات غسيل.",
    mi_rd_desc_2: "“يتم تمكين أخذ العينات السريع وتحسين التصميم من خلال عمليتنا المرنة عبر التعاون الوثيق والتجريب المستمر، مع ضمان الجودة والراحة من الدرجة الأولى من خلال القياس الخبير والدعم الفني.”",
    mi_vision_precision: "“حيث تلتقي الرؤية بالدقة.”",
    mi_shaping_future: "نحن لا نتكيف فقط مع مستقبل الموضة — نحن نشكله.",
    mi_design_title: "ابتكار التصميم، الارتقاء بالأناقة الإبداعية-",
    mi_design_expedition: "مرحباً بكم في رحلة التصميم الخاصة بنا-",
    mi_design_exp_desc: "هذا أكثر من مجرد موضة — إنها حركة. التزام جريء بدفع الحدود الإبداعية، واحتضان التصميم المسؤول، وإشعال التغيير العالمي. سواء كنت تطلق علامة تجارية جديدة، أو تعيد تعريف علامتك التجارية، أو تبحث عن شريك تصميم لإحياء رؤيتك، فإن ApparelBD هو حليفك الإبداعي.",
    mi_co_creation: "الإبداع المشترك هو جوهر عمليتنا. من خلال التعاون مع مواهب تصميم متنوعة، ندمج الإبداع مع رؤية السوق — مما يعزز قدرات عملائنا مع الحفاظ على أصالة العلامة التجارية.",
    mi_crafting_future: "صياغة مستقبل الموضة - الارتقاء بالأسلوب.... إعادة تعريف الأناقة...!!",
    mi_join_us: "انضم إلينا-",
    mi_join_us_desc: "حيث يزدهر الابتكار ويعاد تعريف الموضة.",
    mi_spark_creativity: "لنطلق شرارة الإبداع، ونلهم التغيير، ونشكل المستقبل معاً!!",
    mi_trend_title: "تحليل الاتجاهات: تصميم مدفوع بالرؤية-",
    mi_trend_1: "تتطور الموضة بسرعة، والبقاء في المقدمة يتطلب رؤية استراتيجية.",
    mi_trend_2: "التنبؤ بالاتجاهات العالمية، نتوقع الاتجاهات الناشئة في جميع أنحاء العالم.",
    mi_trend_3: "رؤى الألوان والقصات الموسمية، تنبؤات دقيقة لألوان وأشكال الموسم.",
    mi_trend_4: "تحليل سلوك المستهلك، نتتبع تفضيلات المستهلكين المتغيرة.",
    mi_trend_5: "المقارنة المعيارية التنافسية، رؤى لإبقاء علامتك التجارية متقدمة على المنافسة.",
    mi_insight_quote: "“ابق في المقدمة مع التصميم المدفوع بالرؤية، وتشكيل أزياء الغد اليوم.”",
    mi_studio_title: "استوديو التصميم:",
    mi_studio_sub: "حيث تصبح الأفكار العالمية أزياء أيقونية",
    mi_studio_desc: "في ApparelBD، التصميم أكثر من مجرد عملية — إنه تعاون عبر القارات. تعمل استوديوهاتنا في لندن ودكا بانسجام لتحويل الرؤى والحرفية والإبداع إلى مجموعات أزياء جاهزة للمستقبل ومصنوعة بشكل أخلاقي. معاً، يشكلون نظاماً بيئياً للتصميم حيث تتطور الأفكار، ويتم تحسين الجماليات، وتقود الاستدامة كل خطوة",
    mi_london_title: "استوديو تصميم ApparelBD لندن، المملكة المتحدة:",
    mi_london_leading: "القيادة برؤية، أناقة. إبداع...!!",
    mi_london_desc_long: "يقع استوديو لندن الخاص بنا في قلب المملكة المتحدة، ويقود بمزيج فريد من ذكاء السوق، وابتكار التصميم، والطلاقة الثقافية، والجماليات الخالدة. نحن نصوغ مجموعات تلهم، وتعكس جوهر علامتك التجارية، وتضع اتجاهات جديدة.",
    mi_uk_designers_desc: "بقيادة مصممين من أصل بريطاني ذوي خبرة عالمية عبر علامات تجارية مشهورة للأزياء، يدمج فريقنا الرؤية الإبداعية مع الاستراتيجية التجارية لتقديم تصميمات ثاقبة ومذهلة ومستدامة. من خلال الإبداع المشترك التعاوني، نضخم صوت علامتك التجارية بأهمية عالمية — ونشارك من المفهوم إلى المنتج النهائي.",
    mi_build_future: "لنبنِ مستقبل الموضة معاً!!",
    
