    mi_support_title: "دعم التصميم والإبداع المشترك:",
    mi_support_sub: "شراكة إبداعية شاملة",
    mi_support_text: "في ApparelBD، الإبداع المشترك هو رحلة مشتركة من الابتكار. نحن نتشارك مع العلامات التجارية لدمج هويتها مع خبرتنا في التصميم، لصياغة مجموعات أصلية وجاهزة للسوق. من خلال توحيد وجهات النظر المتنوعة والرؤية الاستراتيجية، نساعد العملاء على قيادة الموضة لغرض وأصالة.",
    mi_support_list_1: "• أخذ العينات السريع يبقي مجموعتك في الموعد المحدد.",
