    mi_support_quote: "“صُنع معاً: شركاء في الإبداع، مصمم للقيادة!!",

    mi_phil_title: "فلسفة التصميم لدينا",
    mi_phil_sub: "ذكاء إبداعي لغرض",
    mi_phil_text: "في ApparelBD، التصميم هو مزيج من الخيال، والاستراتيجية، والمسؤولية. نؤمن بأن كل مجموعة يجب أن تكون مذهلة بصرياً، وسليمة أخلاقياً، وذكية تجارياً — مبنية ليس فقط للآن، بل للمستقبل.",
    mi_approach_built_on: "نهجنا مبني على-",
    mi_app_built_1: "الدمج الإبداعي", mi_app_built_1_sub: "حيث تلتقي الثقافة، والتكنولوجيا، والقصة.",
