    home_about_title: "关于我们",
    home_about_subtitle: "我们是谁... !!",
    home_about_text: "在 ApparelBD，我们相信时尚不仅仅是服装，它是一种不断演变的声明，一种身份的表达。它是时间与地点的文化背景，是感知、渴望、创造力和创新，是个人与社区的价值和信仰。我们通过市场情报、趋势分析、创新设计和道德采购推动时尚向前发展。在强大的质量保证、可靠的物流和卓越服务的支持下，我们致力于为客户提供卓越的价值。",
    home_about_quote: "我们要对时尚进步的承诺涵盖市场情报、趋势分析、创新设计和研发。",
    home_about_section_title: "趋势驱动，道德采购，值得信赖且可追溯 – 您的时尚制造合作伙伴-",
    home_about_section_text: "我们与全球合规的制造商合作，确保可追溯性、质量和过程控制。我们在伦敦和达卡的设计工作室将全球创意与本地人才相融合，专注于研发、趋势驱动的产品以及像迪士尼等标志性授权角色。现场检查和全面的物流支持凸显了我们对负责任、创新制造的承诺。",
    home_about_value_prop: "\"道德采购，可持续发展，卓越制造和优质服务 - 为客户提供增值。\"",
    all_about_us_title: "关于我们的一切",
    all_about_us_desc: "我们相信时尚不仅仅是服装，它是一种不断演变的声明，一种身份的表达，时间与地点的文化背景，感知、渴望、创造力和创新，个人与社区的价值和信仰。",
