    home_fashion_text: "踏上时尚演变之旅 — 引领潮流的设计和尖端技术塑造风格的未来。在 ApparelBD，时尚诉说着身份转变的语言，想象力与科学相遇，传统与创新融合。",
    home_fashion_quote_parallax: "\"时尚不是静止的；它是一种不断演变的艺术形式。为了保持领先，我们必须拥抱变化和创新。\"",
