    about_intro_p1: "我们相信时尚不仅仅是服装，它是一种不断演变的声明，一种身份的表达，时间与地点的文化背景，感知、渴望、创造力和创新，个人与社区的价值和信仰。成立于2024年，我们将创造力、可持续性和卓越制造相结合，提供创新的全球采购解决方案。",
    about_intro_p2: "我们通过市场情报、趋势分析、创新设计和多样化的产品类别推动时尚演变。我们的承诺涵盖道德采购、可持续发展、社会责任和国际合规。凭借值得信赖的制造合作伙伴、质量保证、授权角色生产和端到端物流，我们提供卓越的服务和非凡的客户价值。",
    about_banner_green: "\"提升采购，加强合作- 我们共同成就更多！！\"",
    about_expertise: "我们的专长-",
    about_exp_1: "市场情报，设计支持。",
    about_exp_2: "研发与产品创新。",
    about_exp_3: "道德与负责任的采购，",
