    // About - People
    about_people: "我们的团队：",
    about_people_sub: "我们的团队，我们的力量：推动我们的专业知识..!!",
    about_people_desc: "在 ApparelBD，有目的的时尚是由充满激情的人推动的。我们最大的优势是我们多元化、全球互联的团队——在时尚生命周期的每个阶段提供动力的创新者。从引领潮流的设计和道德采购到精准的产品开发、严格的质量保证和无缝物流，我们的专家以创造力、诚信和对可持续发展的承诺引领潮流。",
    about_people_desc_2: "合作是我们的基础。我们共同提供融合艺术、道德和卓越的解决方案——确保我们创造的每一件作品都具有目的。",
    about_global_pres_title: "全球布局，本地洞察",
    about_global_pres_desc: "总部位于达卡，在达卡和伦敦设有设计工作室，在英国、德国、加拿大和新西兰设有采购办事处，我们将全球趋势与区域专业知识相融合，创造出在本地产生共鸣并符合国际标准的时尚。",
    about_global_pres_desc_2: "全球时尚趋势被转化为注重细节的创新、高质量产品。在强大的制造和采购网络支持下，我们提供时尚必需品和量身定制的解决方案，以满足不断变化的消费者需求。",
    role_designers: "来自英国和孟加拉国工作室的资深设计师",
    role_designers_desc: "将全球美学与本地创意相融合。",
