    // Market Intel Page
    mi_hero_title: "市场情报设计",
    mi_hero_sub: "设计远征",
    mi_fe_title: "时尚演变",
    mi_fe_sub: "重新定义动态风格，未来穿着我们 !!",
    mi_fe_text: "时尚演变不仅仅是一场运动——它是一次蜕变。这是一个想象力与科学共舞的领域，每一个轮廓都在讲述明天的故事。在这里，有远见的设计、无畏的研究和无限的创新汇聚在一起，为动态的世界重新构想时尚。",
    mi_lang_title: "时尚不再只是面料——它是一种语言！！",
    mi_lang_p1: "这是身份转变的生动反映，是用价值观编织的挂毯，古老的线索与未来的形式交织在一起。",
    mi_lang_p2: "在 ApparelBD，演变在我们的 DNA 中。我们的设计师将道德与优雅、传统与技术相融合，打造永恒、面向未来的作品。使用下一代材料和零浪费设计，我们创造了一个风格与可持续性相遇的新时代。",
    mi_lang_footer: "有意义，迷人，用心制作！！",
    mi_quote_1: "“ 时尚以思想的速度移动，随心灵流动 ——演变是它的本质。”",
    mi_rd_title: "研发与创新",
    mi_rd_sub: "“创新风格。激发改变..”",
    mi_rd_desc: "在时尚演变中，我们将尖端研发与创意创新相融合以重新定义时尚——通过先进的面料、装饰和洗涤技术打造耐用、艺术的作品。",
    mi_rd_desc_2: "“通过紧密合作和持续实验，我们的敏捷流程实现了快速采样和设计优化，通过专家试衣和技术支持确保顶级质量和舒适度。”",
    mi_vision_precision: "“愿景与精准相遇的地方。”",
    mi_shaping_future: "我们不仅适应时尚的未来——我们在塑造它。",
    mi_design_title: "设计创新，提升创意优雅-",
    mi_design_expedition: "欢迎来到我们的设计远征-",
    mi_design_exp_desc: "这不仅仅是时尚——这是一场运动。大胆致力于突破创意界限，拥抱负责任的设计，并引发全球变革。无论您是推出新品牌，重新定义品牌，还是寻找设计合作伙伴来实现您的愿景，ApparelBD 都是您的创意盟友。",
    mi_co_creation: "共创是我们流程的核心。通过与多样化的设计人才合作，我们将创造力与市场洞察力相结合——增强客户的能力，同时保持品牌的真实性。",
    mi_crafting_future: "打造时尚未来 - 提升风格.... 重新定义优雅...!!",
    mi_join_us: "加入我们-",
    mi_join_us_desc: "创新蓬勃发展，时尚被重新定义的地方。",
    mi_spark_creativity: "让我们激发创造力，激发改变，共同塑造未来！！",
    mi_trend_title: "趋势分析：洞察驱动的设计-",
    mi_trend_1: "时尚发展迅速，保持领先需要战略洞察力。",
    mi_trend_2: "全球趋势预测，我们预测全球新兴趋势。",
    mi_trend_3: "季节性色彩与轮廓洞察，对季节色彩和形状的精准预测。",
    mi_trend_4: "消费者行为分析，我们跟踪不断变化的消费者偏好。",
    mi_trend_5: "竞争基准分析，洞察力使您的品牌在竞争中保持领先。",
    mi_insight_quote: "“通过洞察驱动的设计保持领先，塑造明天的时尚。”",
    mi_studio_title: "设计工作室：",
    mi_studio_sub: "全球创意成为标志性时尚的地方",
    mi_studio_desc: "在 ApparelBD，设计不仅仅是一个过程——它是跨大陆的合作。我们的伦敦和达卡工作室和谐工作，将洞察力、工艺和创造力转化为面向未来、道德制造的时尚系列。它们共同形成了一个设计生态系统，在这里思想演变，美学得到提炼，可持续性引领每一步",
    mi_london_title: "ApparelBD 英国伦敦设计工作室：",
    mi_london_leading: "以洞察力、优雅、创造力引领...!!",
    mi_london_desc_long: "位于英国中心地带，我们的伦敦工作室以独特的市场情报、设计创新、文化流畅性和永恒美学引领潮流。我们打造能够激发灵感、反映品牌精髓并设定新趋势的系列。",
    mi_uk_designers_desc: "由具有知名时尚品牌全球经验的英国本土设计师推动，我们的团队将创意愿景与商业战略相融合，提供有洞察力、引人注目且可持续的设计。通过协作共创，我们以全球相关性放大您的品牌声音——从概念到最终产品进行合作。",
