    mi_dhaka_title: "ApparelBD 孟加拉国达卡设计工作室：",
    mi_dhaka_sub: "打造未来：传承、愿景和可扩展设计！！",
    mi_dhaka_text: "在孟加拉国达卡——一座以其丰富纺织遗产而闻名的城市——我们的工作室将传统工艺与尖端全球设计相结合。在这里，创造力植根于文化深度，并通过与我们伦敦团队的紧密整合得到增强。",
