    mi_support_title: "设计支持与共创：",
    mi_support_sub: "端到端创意合作伙伴关系",
    mi_support_text: "在 ApparelBD，共创是一段共同的创新旅程。我们与品牌合作，将其身份与我们的设计专长相融合，打造真实、市场就绪的系列。通过结合多样化的视角和战略洞察力，我们帮助客户以目的和原创性引领时尚。",
    mi_support_list_1: "• 快速采样让您的系列按计划进行。",
    mi_support_list_2: "• 试衣和设计咨询确保质量和性能。",
    mi_support_list_3: "• 趋势洞察使您的设计与市场保持一致。",
