    home_about_title: "OVER ONS",
    home_about_subtitle: "Wie We Zijn... !!",
    home_about_text: "Bij ApparelBD geloven we dat mode niet alleen over Kleding gaat, het is een steeds evoluerend statement, een uitdrukking van Identiteit. Culturele context van tijd en plaats, perceptie, ambitie, creativiteit en innovatie, waarde en overtuiging van individu en gemeenschap. Wij stimuleren mode door middel van marktinformatie, trendanalyse, innovatief ontwerp en ethische inkoop. Ondersteund door sterke kwaliteitsborging, betrouwbare logistiek en uitzonderlijke service, streven wij ernaar uitstekende waarde te leveren aan onze klanten.",
    home_about_quote: "Onze toewijding aan modevooruitgang omvat marktinformatie, trendanalyse, innovatief ontwerp en R&D.",
    home_about_section_title: "Trendgedreven, Ethisch Ingekocht, Vertrouwd & Traceerbaar – Uw Mode Productiepartner-",
    home_about_section_text: "Wij werken samen met wereldwijd conforme fabrikanten om traceerbaarheid, kwaliteit en procesbeheersing te garanderen. Onze ontwerpstudio's in Londen en Dhaka combineren Wereldwijde Creativiteit met lokaal talent, gericht op R&D, trendgedreven producten en iconische gelicentieerde karakters zoals Disney en anderen. Inspecties ter plaatse en volledige logistieke ondersteuning benadrukken onze toewijding aan verantwoorde, innovatieve productie.",
    home_about_value_prop: "\"Ethische inkoop, duurzaamheid, productie-uitmuntendheid en superieure service - levert toegevoegde Klantwaarde.\"",
