    all_about_us_desc: "Wij geloven dat Mode niet alleen over Kleding gaat, het is een steeds evoluerend statement, een uitdrukking van Identiteit, Culturele context van tijd en plaats, perceptie, ambitie, creativiteit en innovatie, waarde en overtuiging van individu en gemeenschap.",
