    about_welcome: "Welkom bij ApparelBD, Waar Mode Integriteit Ontmoet!!",
    about_intro_title: "Betrouwbare Strategische, Duurzame en Ethische Wereldwijde Inkooppartner!!",
    about_intro_p1: "Wij geloven dat Mode niet alleen over Kleding gaat, het is een steeds evoluerend statement, een uitdrukking van Identiteit, Culturele context van tijd en plaats, perceptie, ambitie, creativiteit en innovatie, waarde en overtuiging van individu en gemeenschap. Opgericht in 2024, combineren wij creativiteit, duurzaamheid en productie-uitmuntendheid om innovatieve wereldwijde inkoopoplossingen te leveren.",
    about_intro_p2: "Wij stimuleren mode-evolutie door middel van marktinformatie, trendanalyse, innovatief ontwerp en veelzijdige productcategorieën. Onze toewijding omvat ethische inkoop, duurzaamheid, sociale verantwoordelijkheid en internationale naleving. Met vertrouwde productiepartners, kwaliteitsborging, productie van gelicentieerde karakters en end-to-end logistiek leveren wij superieure service en uitzonderlijke klantwaarde.",
