    // About - People
    about_people: "ONZE MENSEN:",
    about_people_sub: "Onze Mensen, Onze Kracht: Expertise die Ons Aandrijft..!!",
    about_people_desc: "Bij ApparelBD wordt doelgerichte mode gedreven door gepassioneerde mensen. Onze grootste kracht is ons diverse, wereldwijd verbonden team—innovators die elke fase van de modelevenscyclus aandrijven. Van trendgericht ontwerp en ethische inkoop tot nauwkeurige productontwikkeling, strenge kwaliteitsborging en naadloze logistiek, onze experts leiden met creativiteit, integriteit en een toewijding aan duurzaamheid.",
    about_people_desc_2: "Samenwerking is onze basis. Samen leveren we oplossingen die kunstzinnigheid, ethiek en uitmuntendheid combineren—ervoor zorgend dat elk stuk dat we creëren een doel heeft.",
    about_global_pres_title: "Wereldwijde Aanwezigheid, Lokaal Inzicht",
    about_global_pres_desc: "Met het hoofdkantoor in Dhaka, en ontwerpstudio's in Dhaka en Londen, en inkoopkantoren in het VK, Duitsland, Canada en Nieuw-Zeeland, combineren we wereldwijde trends met regionale expertise om mode te creëren die lokaal resoneert en voldoet aan internationale normen.",
    about_global_pres_desc_2: "Wereldwijde modetrends worden vertaald in innovatieve, hoogwaardige producten met veel aandacht voor detail. Ondersteund door sterke productie- en inkoopnetwerken, worden mode-essentials en op maat gemaakte oplossingen geleverd om te voldoen aan de veranderende behoeften van de consument.",
