    // About - Mission/Vision
    about_mission: "Missie:",
    about_mission_desc: "Het leveren van innovatieve, ethische mode-inkoop met uitzonderlijk ontwerp, kwaliteit en productie—met prioriteit voor trendgedreven ontwerpcreatie, duurzaamheid, traceerbaarheid en duurzame partnerschappen voor wederzijds succes en positieve impact.",
    about_vision: "Visie:",
    about_vision_desc: "ApparelBD streeft ernaar een wereldleider te zijn in kledinginkoop, nieuwe normen te stellen in ontwerpinnovatie, klantenondersteuning en ethische inkoop, terwijl creativiteit, duurzaamheid en traceerbaarheid worden bevorderd om blijvende waarde te leveren.",
    about_services_sub: "Wat We Doen...",
    
    // About - Values
    about_values_title: "Waarden en Inkoopfilosofie",
    val_customer_title: "Klantgerichtheid",
    val_customer_desc: "Onze klanten vormen de kern van alles wat we doen. We luisteren naar hun behoeften en streven naar tevredenheid door proactieve betrokkenheid en superieure service.",
    val_integrity_title: "Integriteit en Ethiek",
    val_integrity_desc: "We zijn toegewijd aan vertrouwen, integriteit en ethiek in alle interacties, handhaven hoge normen van eerlijkheid en bevorderen transparantie.",
    val_transparency_title: "Transparantie, Verantwoording en Vertrouwen",
    val_transparency_desc: "We geven prioriteit aan transparantie, verantwoording en vertrouwen om open communicatie en duurzame partnerschappen op basis van wederzijds respect te bevorderen.",
    val_price_title: "Concurrerende Prijs en Flexibiliteit",
    val_price_desc: "We leveren premium kleding tegen concurrerende prijzen zonder in te boeten aan kwaliteit, en zorgen voor uitzonderlijk vakmanschap en duurzaamheid door strenge kwaliteitsborging.",
    val_quality_title: "Kwaliteit",
    val_quality_desc: "Wij geloven dat mensen het verschil maken. Ons team staat centraal in ons succes en toont uitzonderlijke capaciteiten. We respecteren elk individu en waarderen hun bijdragen.",
    val_safety_title: "Veiligheid, Beveiliging en Werkomgeving",
    val_safety_desc: "Veiligheid en beveiliging zijn prioriteiten, ondersteund door strikte protocollen. We bevorderen teamwerk en geven prioriteit aan ethische inkoop, welzijn van werknemers en duurzaamheid.",
    val_improvement_title: "Streven naar continue verbetering en uitmuntendheid",
    val_improvement_desc: "We omarmen een cultuur van toewijding aan continue uitmuntendheid en verbetering, toegewijd aan het overtreffen van verwachtingen in alle activiteiten.",
    val_innovation_title: "Innovatie, Creativiteit en Marktinformatie",
    val_innovation_desc: "We richten ons op innovatie in ontwerp en stof, gebruiken marktonderzoek om trends te voorspellen en aan de eisen van de klant te voldoen, en stellen nieuwe maatstaven in de mode-industrie.",
    val_social_title: "Sociale Verantwoordelijkheid",
    val_social_desc: "We geven prioriteit aan sociale verantwoordelijkheid en duurzaamheid door ethische arbeidspraktijken, eerlijke lonen, gemeenschapsontwikkeling en duurzame inkoop.",
    
    about_collab_title: "We zijn zo enthousiast en kijken er reikhalzend naar uit om met u samen te werken en samen te werken om superieure inkoopoplossingen te bieden en onze capaciteiten te verbeteren!!",
    about_collab_sub: "We wachten erop om uw partner te zijn, dus Laten we samenwerken...!!!",

