    // Products Page
    prod_hero_title: "Onze Productlijnen",
    prod_hero_subtitle: "Gediversifieerde, Hoogwaardige en Breed Scala aan Productcategorieën",
    prod_cat_title: "Productcategorieën",
    prod_intro: "Ontdek ons uitgebreide assortiment hoogwaardige kleding. Elke categorie vertegenwoordigt onze toewijding aan uitmuntendheid, innovatie en diverse modebehoeften.",
    prod_drag_hint: "(Sleep de galerijen naar links of rechts om te verkennen)",
    prod_desc_home: "Op het kruispunt van innovatie en stijl bieden wij een uitgebreid assortiment producten om te voldoen aan diverse modevoorkeuren, waarbij tijdloze elegantie wordt gecombineerd met de nieuwste trends.",
    prod_desc_home_2: "Onze missie is om uw inkooptoeleveringsketen van ontwerp tot levering te verbeteren. Met een focus op 12 verschillende categorieën stemmen we inkoopoplossingen af om effectief aan uw behoeften te voldoen.",
    prod_custom_sol: "Een aangepaste inkoopoplossing nodig?",
    
    // Market Intel Page
    mi_hero_title: "Marktinformatie Ontwerp",
    mi_hero_sub: "Ontwerpexpeditie",
    mi_fe_title: "MODE-EVOLUTIE",
    mi_fe_sub: "Stijl in Beweging Herdefiniëren, Waar de Toekomst Ons Draagt !!",
    mi_fe_text: "Mode-evolutie is niet zomaar een beweging—het is een metamorfose. Een rijk waar verbeelding danst met wetenschap, en elk silhouet een verhaal van morgen vertelt. Hier komen visionair ontwerp, onbevreesd onderzoek en grenzeloze innovatie samen om mode opnieuw te verbeelden voor een wereld in beweging.",
    mi_lang_title: "Mode is niet langer alleen stof— het is een Taal!!",
    mi_lang_p1: "Een levende weerspiegeling van veranderende identiteiten, een wandtapijt geweven met waarden, waar oude draden verstrengelen met toekomstige vormen.",
    mi_lang_p2: "Bij ApparelBD zit evolutie in ons DNA. Onze ontwerpers combineren ethiek met elegantie, traditie met technologie, en creëren tijdloze, toekomstgerichte stukken. Met behulp van materialen van de volgende generatie en nul-afval ontwerp creëren we een nieuw tijdperk waarin stijl duurzaamheid ontmoet.",
    mi_lang_footer: "Betekenisvol, Betoverend, Bewust Gemaakt!!",
    mi_quote_1: "“ Mode beweegt met de snelheid van de gedachte en stroomt met de geest —Evolutie is haar Essentie.”",
    mi_rd_title: "Onderzoek & Ontwikkeling en Innovatie",
    mi_rd_sub: "“Stijl Innoveren. Verandering Inspireren..”",
    mi_rd_desc: "Bij Mode-evolutie combineren we geavanceerde R&D met creatieve innovatie om mode te herdefiniëren—duurzame, artistieke stukken makend door geavanceerde stoffen, verfraaiingen en wastechnieken.",
    mi_rd_desc_2: "“Snelle bemonstering en ontwerpverfijning worden mogelijk gemaakt door ons flexibele proces via nauwe samenwerking en voortdurend experimenteren, met topkwaliteit en comfort gegarandeerd door deskundige pasvorm- en technische ondersteuning.”",
    mi_vision_precision: "“Waar Visie Precisie Ontmoet.”",
    mi_shaping_future: "We passen ons niet alleen aan de toekomst van mode aan —we geven deze vorm.",
    mi_design_title: "Ontwerpinnovatie, Creatieve Elegantie Verhogen-",
    mi_design_expedition: "Welkom bij Onze Ontwerpexpeditie-",
    mi_design_exp_desc: "Dit is meer dan mode—het is een beweging. Een gedurfde toewijding om creatieve grenzen te verleggen, verantwoord ontwerp te omarmen en wereldwijde verandering te ontketenen. Of u nu een nieuw label lanceert, uw merk herdefinieert of een ontwerppartner zoekt om uw visie tot leven te brengen, ApparelBD is uw creatieve bondgenoot.",
    mi_co_creation: "Co-creatie is de kern van ons proces. Door samen te werken met divers ontwerptalent, combineren we creativiteit met marktinzicht—waardoor de capaciteiten van onze klanten worden versterkt terwijl de merkauthenticiteit behouden blijft.",
    mi_crafting_future: "De Toekomst van Mode Vormgeven- Stijl Verhogen.... Elegantie Herdefiniëren...!!",
    mi_join_us: "Doe met ons mee-",
    mi_join_us_desc: "Waar innovatie gedijt en mode wordt geherdefinieerd.",
    mi_spark_creativity: "Laten we creativiteit aanwakkeren, verandering inspireren en de toekomst samen vormgeven!!",
    mi_trend_title: "Trendanalyse: Inzichtgestuurd Ontwerp-",
    mi_trend_1: "Mode evolueert snel, en voorop blijven vereist strategisch inzicht.",
    mi_trend_2: "Wereldwijde Trendvoorspelling, Wij voorspellen opkomende trends wereldwijd.",
    mi_trend_3: "Seizoensgebonden Kleur & Silhouet Inzichten, Nauwkeurige voorspellingen voor de kleuren en vormen van het seizoen.",
    mi_trend_4: "Consumentengedragsanalyse, Wij volgen veranderende consumentenvoorkeuren.",
    mi_trend_5: "Competitieve Benchmarking, Inzichten om uw merk de concurrentie voor te blijven.",
    mi_insight_quote: "“Blijf Voorop met Inzichtgestuurd Ontwerp, Vormgeven aan de Mode van Morgen Vandaag.”",
    mi_studio_title: "ONTWERPSTUDIO:",
    mi_studio_sub: "Waar Wereldwijde Ideeën Iconische Mode Worden",
    mi_studio_desc: "Bij ApparelBD is ontwerp meer dan een proces — het is een continent-overstijgende samenwerking. Onze studio's in Londen en Dhaka werken in harmonie om inzichten, vakmanschap en creativiteit om te zetten in toekomstbestendige, ethisch gemaakte modecollecties. Samen vormen ze een ontwerpeosysteem waar ideeën evolueren, esthetiek wordt verfijnd en duurzaamheid elke stap leidt",
    mi_london_title: "ApparelBD Londen, VK Ontwerpstudio:",
    mi_london_leading: "Leiden met Inzicht, Elegantie. Creativiteit...!!",
    mi_london_desc_long: "Gevestigd in het hart van het VK, leidt onze studio in Londen met een unieke mix van marktinformatie, ontwerpinnovatie, culturele vloeiendheid en tijdloze esthetiek. Wij maken collecties die inspireren, de essentie van uw merk weerspiegelen en nieuwe trends zetten.",
    mi_uk_designers_desc: "Gedreven door in het VK geboren ontwerpers met wereldwijde ervaring bij gerenommeerde modemerken, combineert ons team creatieve visie met commerciële strategie om inzichtelijke, opvallende en duurzame ontwerpen te leveren. Door gezamenlijke co-creatie versterken we de stem van uw merk met wereldwijde relevantie—partnerend van concept tot eindproduct.",
    mi_build_future: "Laten we samen de toekomst van mode bouwen!!",
    
    mi_studio_highlight_title: "STUDIO HOOGTEPUNT:",
