    mi_dhaka_title: "ApparelBD Dhaka, Bangladesh Ontwerpstudio:",
    mi_dhaka_sub: "De Toekomst Maken: Erfgoed, Visie en Schaalbaar Ontwerp!!",
    mi_dhaka_text: "In Dhaka, Bangladesh — een stad die bekend staat om zijn rijke textielerfgoed — brengt onze studio traditioneel vakmanschap samen met geavanceerd wereldwijd ontwerp. Hier is creativiteit gegrondvest in culturele diepgang en versterkt door nauwe integratie met ons team in Londen.",
