    mi_support_title: "Ontwerpondersteuning en Co-Creatie:",
    mi_support_sub: "End-to-End Creatief Partnerschap",
    mi_support_text: "Bij ApparelBD is co-creatie een gedeelde reis van innovatie. We werken samen met merken om hun identiteit te combineren met onze ontwerpexpertise, om authentieke, marktklare collecties te maken. Door diverse perspectieven en strategisch inzicht te verenigen, helpen we klanten mode te leiden met doel en originaliteit.",
    mi_support_list_1: "• Snelle bemonstering houdt uw collectie op schema.",
    mi_support_list_2: "• Pasvorm- en ontwerpconsulten zorgen voor kwaliteit en prestaties.",
    mi_support_list_3: "• Trendinzichten stemmen uw ontwerpen af op de markt.",
    mi_support_list_4: "• Duurzame begeleiding ondersteunt doelgericht creëren.",
    mi_support_list_5: "• Ondersteuning bij zowel nieuwe als bestaande lijnontwikkeling.",
    mi_support_list_6: "• Zorgen dat elk ontwerp de visie van het merk weerspiegelt",
    mi_support_quote: "“Samen Gemaakt: Partners in Creativiteit, Ontworpen om te Leiden!!",

    mi_phil_title: "Onze Ontwerpfilosofie",
    mi_phil_sub: "Creatieve Intelligentie met Doel",
    mi_phil_text: "Bij ApparelBD is ontwerp een samensmelting van verbeelding, strategie en verantwoordelijkheid. Wij geloven dat elke collectie visueel opvallend, ethisch verantwoord en commercieel slim moet zijn — niet alleen gebouwd voor nu, maar voor de toekomst.",
    mi_approach_built_on: "Onze Aanpak Is Gebaseerd Op-",
