    home_about_text: "Chez ApparelBD, nous croyons que la mode n'est pas seulement une question de Vêtements, c'est une déclaration en constante évolution, une expression de l'Identité. Contexte culturel du temps et du lieu, perception, aspiration, créativité et innovation, valeur et croyance de l'individu et de la communauté. Nous faisons avancer la mode grâce à la veille commerciale, l'analyse des tendances, le design innovant et l'approvisionnement éthique. Soutenus par une assurance qualité solide, une logistique fiable et un service exceptionnel, nous visons à offrir une valeur exceptionnelle à nos clients.",
    home_about_quote: "Notre engagement envers la progression de la mode couvre la veille commerciale, l'analyse des tendances, le design innovant et la R&D.",
    home_about_section_title: "Axé sur les Tendances, Approvisionnement Éthique, Fiable & Traçable – Votre Partenaire de Fabrication de Mode-",
    home_about_section_text: "Nous collaborons avec des fabricants conformes aux normes mondiales pour assurer la traçabilité, la qualité et le contrôle des processus. Nos studios de design à Londres et à Dhaka allient Créativité Mondiale et talent local, en se concentrant sur la R&D, les produits axés sur les tendances et les personnages sous licence emblématiques comme Disney et d'autres. Les inspections sur site et le support logistique complet soulignent notre engagement envers une fabrication responsable et innovante.",
