    about_welcome: "Bienvenue chez ApparelBD, Où la Mode Rencontre l'Intégrité !!",
    about_intro_title: "Partenaire d'Approvisionnement Mondial Fiable, Stratégique, Durable et Éthique !!",
    about_intro_p1: "Nous croyons que la Mode n'est pas seulement une question de Vêtements, c'est une déclaration en constante évolution, une expression de l'Identité, Contexte culturel du temps et du lieu, perception, aspiration, créativité et innovation, valeur et croyance de l'individu et de la communauté. Fondée en 2024, nous allions créativité, durabilité et excellence manufacturière pour offrir des solutions d'approvisionnement mondial innovantes.",
    about_intro_p2: "Nous stimulons l'évolution de la mode grâce à la veille commerciale, l'analyse des tendances, le design innovant et des catégories de produits polyvalentes. Notre engagement couvre l'approvisionnement éthique, la durabilité, la responsabilité sociale et la conformité internationale. Avec des partenaires de fabrication de confiance, une assurance qualité, la production de personnages sous licence et une logistique de bout en bout, nous offrons un service supérieur et une valeur client exceptionnelle.",
    about_banner_green: "\"Élever l'Approvisionnement, Renforcer le Partenariat- Ensemble Nous Accomplissons Plus !!\"",
