    about_ds_focus_1_label: "Design & Collaboration :",
    about_ds_focus_1_text: "Designs durables et axés sur les tendances propulsés par des Designers experts basés dans les Studios de Londres et Dhaka.",
    about_ds_focus_2_label: "Façonner l'Avenir :",
    about_ds_focus_2_text: "Repousser les limites de la mode pour le changement et la durabilité.",

    // About - People
    about_people: "NOS GENS :",
    about_people_sub: "Nos Gens, Notre Force : L'Expertise qui Nous Propulse..!!",
    about_people_desc: "Chez ApparelBD, la mode utile est portée par des personnes passionnées. Notre plus grande force est notre équipe diversifiée et connectée mondialement—des innovateurs qui propulsent chaque étape du cycle de vie de la mode. Du design tendance et de l'approvisionnement éthique au développement produit précis, à l'assurance qualité rigoureuse et à la logistique sans faille, nos experts mènent avec créativité, intégrité et un engagement envers la durabilité.",
    about_people_desc_2: "La collaboration est notre fondation. Ensemble, nous livrons des solutions qui allient art, éthique et excellence—en veillant à ce que chaque pièce que nous créons ait un but.",
    about_global_pres_title: "Présence Mondiale, Aperçu Local",
    about_global_pres_desc: "Basés à Dhaka, avec des studios de design à Dhaka et Londres, et des bureaux d'approvisionnement au Royaume-Uni, en Allemagne, au Canada et en Nouvelle-Zélande, nous fusionnons les tendances mondiales avec l'expertise régionale pour créer une mode qui résonne localement et répond aux normes internationales.",
    about_global_pres_desc_2: "Les tendances mondiales de la mode sont traduites en produits innovants et de haute qualité avec une attention particulière aux détails. Soutenus par de solides réseaux de fabrication et d'approvisionnement, des essentiels de la mode et des solutions sur mesure sont livrés pour répondre aux besoins évolutifs des consommateurs.",
    role_designers: "Designers Experts des Studios du Royaume-Uni et du Bangladesh",
