    // About - Mission/Vision
    about_mission: "Mission :",
    about_mission_desc: "Livrer un approvisionnement de mode innovant et éthique avec un design, une qualité et une fabrication exceptionnels—en privilégiant la création de design axée sur les tendances, la durabilité, la traçabilité et des partenariats durables pour un succès mutuel et un impact positif.",
    about_vision: "Vision :",
    about_vision_desc: "ApparelBD vise à être un leader mondial dans l'approvisionnement de vêtements, établissant de nouvelles normes en matière d'innovation design, de support client et d'approvisionnement éthique, tout en promouvant la créativité, la durabilité et la traçabilité pour offrir une valeur durable.",
