    val_customer_desc: "Nos clients sont au cœur de tout ce que nous faisons. Nous écoutons leurs besoins et visons la satisfaction par un engagement proactif et un service supérieur.",
    val_integrity_title: "Intégrité et Éthique",
    val_integrity_desc: "Nous nous engageons à la confiance, l'intégrité et l'éthique dans toutes les interactions, en maintenant des normes élevées d'honnêteté et en promouvant la transparence.",
    val_transparency_title: "Transparence, Responsabilité et Confiance",
    val_transparency_desc: "Nous privilégions la transparence, la responsabilité et la confiance pour favoriser une communication ouverte et des partenariats durables basés sur le respect mutuel.",
    val_price_title: "Prix Compétitif et Flexibilité",
    val_price_desc: "Nous livrons des vêtements haut de gamme à des prix compétitifs sans compromettre la qualité, assurant un savoir-faire exceptionnel et une durabilité grâce à une assurance qualité rigoureuse.",
    val_quality_title: "Qualité",
    val_quality_desc: "Nous croyons que les gens font la différence. Notre équipe est au cœur de notre succès, montrant des capacités exceptionnelles. Nous respectons chaque individu et valorisons leurs contributions.",
    val_safety_title: "Sûreté, Sécurité et Environnement de Travail",
    val_safety_desc: "La sûreté et la sécurité sont des priorités, soutenues par des protocoles stricts. Nous promouvons le travail d'équipe et privilégions l'approvisionnement éthique, le bien-être des travailleurs et la durabilité.",
    val_improvement_title: "S'efforcer pour l'amélioration continue et l'excellence",
    val_improvement_desc: "Nous adoptons une culture de dévouement à l'excellence et à l'amélioration continues, engagés à dépasser les attentes dans toutes les opérations.",
    val_innovation_title: "Innovation, Créativité et Veille Commerciale",
    val_innovation_desc: "Nous nous concentrons sur l'innovation dans le design et le tissu, utilisant des études de marché pour prévoir les tendances et répondre aux demandes des clients, établissant de nouvelles références dans l'industrie de la mode.",
    val_social_title: "Responsabilité Sociale",
    val_social_desc: "Nous privilégions la responsabilité sociale et la durabilité par des pratiques de travail éthiques, des salaires équitables, le développement communautaire et l'approvisionnement durable.",
    
