    // Home Page
    home_hero_title: "Engagiert für die Mode-Evolution durch...",
    home_hero_subtitle: "Marktinformationen Designunterstützung, Produktinnovation & Neuheit, Breit gefächerte vielseitige Produkte",
    home_quote: "Der Weg zum Anfangen ist, mit dem Reden aufzuhören und mit dem Tun zu beginnen.",
