    home_about_title: "ÜBER UNS",
    home_about_subtitle: "Wer wir sind... !!",
    home_about_text: "Bei ApparelBD glauben wir, dass Mode nicht nur Kleidung ist, sondern ein sich ständig weiterentwickelndes Statement, ein Ausdruck von Identität. Kultureller Kontext von Zeit und Ort, Wahrnehmung, Anspruch, Kreativität und Innovation, Wert und Glaube von Individuum und Gemeinschaft. Wir treiben Mode durch Marktintelligenz, Trendanalyse, innovatives Design und ethische Beschaffung voran. Unterstützt durch starke Qualitätssicherung, zuverlässige Logistik und außergewöhnlichen Service, streben wir danach, unseren Kunden herausragenden Wert zu liefern.",
    home_about_quote: "Unser Engagement für den Fortschritt der Mode umfasst Marktintelligenz, Trendanalyse, innovatives Design und F&E.",
    home_about_section_title: "Trendorientiert, Ethisch Beschafft, Vertrauenswürdig & Rückverfolgbar – Ihr Partner für Modefertigung-",
    home_about_section_text: "Wir arbeiten mit weltweit konformen Herstellern zusammen, um Rückverfolgbarkeit, Qualität und Prozesskontrolle sicherzustellen. Unsere Designstudios in London und Dhaka verbinden globale Kreativität mit lokalem Talent und konzentrieren sich auf F&E, trendorientierte Produkte und ikonische Lizenzcharaktere wie Disney und andere. Vor-Ort-Inspektionen und volle logistische Unterstützung unterstreichen unser Engagement für verantwortungsvolle, innovative Fertigung.",
    home_about_value_prop: "\"Ethische Beschaffung, Nachhaltigkeit, Fertigungsexzellenz und überlegener Service - liefern zusätzlichen Kundenwert.\"",
    all_about_us_title: "Alles über uns",
    all_about_us_desc: "Wir glauben, dass Mode nicht nur Kleidung ist, sondern ein sich ständig weiterentwickelndes Statement, ein Ausdruck von Identität, kultureller Kontext von Zeit und Ort, Wahrnehmung, Anspruch, Kreativität und Innovation, Wert und Glaube von Individuum und Gemeinschaft.",
    home_fashion_title: "Mode-Evolution",
    home_fashion_subtitle: "Wo Trends beginnen — Modedesign in Bewegung... !!",
    home_fashion_text: "Begeben Sie sich auf die Reise der Mode-Evolution — wo trendsetzendes Design und Spitzentechnologie die Zukunft des Stils formen. Bei ApparelBD spricht Mode die Sprache wechselnder Identitäten, wo Fantasie auf Wissenschaft trifft und Tradition mit Innovation verschmilzt.",
    home_fashion_quote_parallax: "\"Mode ist nicht statisch; sie ist eine sich ständig weiterentwickelnde Kunstform. Um vorne zu bleiben, müssen wir Wandel und Innovation annehmen.\"",
    eth_banner_text: "Unsere Partner erfüllen internationale Sozial- und Umweltstandards, um sowohl Menschen als auch den Planeten zu schützen.",
    earth_quote: "\"Die Erde gehört nicht uns, wir gehören der Erde!\"",
    inquiry_title: "Wir sind bestrebt, Ihnen überlegenen Wert zu liefern",
    inquiry_subtitle: "Um bei uns anzufragen",

    // Home - About Slider
    home_slide_1_title: "Mode-Evolution", home_slide_1_desc: "Von Tradition zu Trend, eine Reise durch die Mode-Evolution",
    home_slide_2_title: "F&E und Innovation", home_slide_2_desc: "Das Morgen gestalten, die zukunftsorientierten F&E-Initiativen in der Stoffinnovation, die den Modefortschritt transformieren..",
    home_slide_3_title: "Ethische Beschaffung", home_slide_3_desc: "Menschen und Gesellschaft an erste Stelle setzen, unsere Praktiken der ethischen Beschaffung gehen weiter.",
    home_slide_4_title: "Nachhaltigkeit", home_slide_4_desc: "Unser Planet, unsere Verantwortung, für einen grüneren Planeten!! Förderung der ökologischen Nachhaltigkeit....",
    home_slide_5_title: "Fertigungsexzellenz", home_slide_5_desc: "Potenzial freisetzen, Innovieren, Optimieren, Übertreffen, Fertigungsexzellenz vorantreiben...",
    home_slide_6_title: "Qualitätssicherung", home_slide_6_desc: "Präzision in der Praxis, die Evolution von Labortests in der Qualitätssicherung.",
    home_slide_7_title: "Faire Rückverfolgbarkeit", home_slide_7_desc: "Transparenz innovieren, faire Rückverfolgbarkeit in Aktion..",
    home_slide_8_title: "Versand", home_slide_8_desc: "Effizienz in Bewegung: Optimierung Ihrer Lieferkette",
    home_slide_9_title: "Nachhaltigkeit", home_slide_9_desc: "Unseren Planeten reinigen, die Suche nach sauberem Wasser....",
    home_slide_10_title: "Einzelhandelsgeschäft und glücklicher Kunde", home_slide_10_desc: "Mode für jeden Körper: Umarmen Sie Ihren einzigartigen Stil, neueste Trends im Inneren!!!",
    home_slide_11_title: "Disney und Lizenzcharakter-Produkte", home_slide_11_desc: "Tragen Sie Ihre Fantasie: Disney und andere Traumcharaktere, die charakteristischen Ikonen erwachen zum Leben!!",
