    // About Page
    about_hero_title: "ÜBER UNS",
    about_hero_sub: "Wer wir sind",
    about_welcome: "Willkommen bei ApparelBD, wo Mode auf Integrität trifft!!",
    about_intro_title: "Zuverlässiger strategischer, nachhaltiger und ethischer globaler Beschaffungspartner!!",
    about_intro_p1: "Wir glauben, dass Mode nicht nur Kleidung ist, sondern ein sich ständig weiterentwickelndes Statement, ein Ausdruck von Identität, kultureller Kontext von Zeit und Ort, Wahrnehmung, Anspruch, Kreativität und Innovation, Wert und Glaube von Individuum und Gemeinschaft. Gegründet im Jahr 2024, verbinden wir Kreativität, Nachhaltigkeit und Fertigungsexzellenz, um innovative globale Beschaffungslösungen zu liefern.",
    about_intro_p2: "Wir treiben die Mode-Evolution durch Marktintelligenz, Trendanalyse, innovatives Design und vielseitige Produktkategorien voran. Unser Engagement umfasst ethische Beschaffung, Nachhaltigkeit, soziale Verantwortung und internationale Compliance. Mit vertrauenswürdigen Fertigungspartnern, Qualitätssicherung, Produktion von Lizenzcharakteren und End-to-End-Logistik liefern wir überlegenen Service und außergewöhnlichen Kundenwert.",
    about_banner_green: "\"Beschaffung verbessern, Partnerschaft stärken - Gemeinsam erreichen wir mehr!!\"",
    about_expertise: "UNSERE EXPERTISE-",
    about_exp_1: "Marktintelligenz, Designunterstützung.",
    about_exp_2: "F&E & Produktinnovation.",
    about_exp_3: "Ethische & verantwortungsvolle Beschaffung,",
    about_exp_4: "Nachhaltigkeit & CSR",
    about_exp_5: "Qualitätssicherung & Fertigungsexzellenz",
    about_exp_6: "Diversifiziertes Produktmanagement",
    about_exp_7: "Beschaffung von lizenzierten Charakterprodukten",
    about_exp_8: "Führung & Branchenexpertise",
    
    // About - Design Studio
    about_ds_title: "DESIGNSTUDIO:",
    about_ds_london: "Designstudio in London, UK",
    about_ds_london_desc: "Das ApparelBD London Studio kreiert elegante, trendorientierte Kollektionen unter der Leitung von hauseigenen britischen Experten-Designern.",
    about_ds_dhaka: "Designstudio in Dhaka, Bangladesch",
    about_ds_dhaka_desc: "Unser Studio in Dhaka verbindet lokales Handwerk mit globalen Trends und liefert innovative, hochwertige Designs.",
    about_ds_focus: "Wir konzentrieren uns auf",
    about_ds_focus_1_label: "Design & Zusammenarbeit:",
    about_ds_focus_1_text: "Nachhaltige, trendorientierte Designs, angetrieben von Experten-Designern in den Studios in London und Dhaka.",
