    // About - People
    about_people: "UNSERE MENSCHEN:",
    about_people_sub: "Unsere Menschen, unsere Stärke: Expertise, die uns antreibt..!!",
    about_people_desc: "Bei ApparelBD wird zweckmäßige Mode von leidenschaftlichen Menschen angetrieben. Unsere größte Stärke ist unser vielfältiges, global vernetztes Team – Innovatoren, die jede Phase des Modelebenszyklus antreiben. Von trendorientiertem Design und ethischer Beschaffung bis hin zu präziser Produktentwicklung, strenger Qualitätssicherung und nahtloser Logistik führen unsere Experten mit Kreativität, Integrität und einem Engagement für Nachhaltigkeit.",
    about_people_desc_2: "Zusammenarbeit ist unser Fundament. Gemeinsam liefern wir Lösungen, die Kunstfertigkeit, Ethik und Exzellenz verbinden – und stellen sicher, dass jedes Stück, das wir kreieren, einen Zweck erfüllt.",
    about_global_pres_title: "Globale Präsenz, lokaler Einblick",
    about_global_pres_desc: "Mit Hauptsitz in Dhaka, Designstudios in Dhaka und London sowie Beschaffungsbüros in Großbritannien, Deutschland, Kanada und Neuseeland verbinden wir globale Trends mit regionaler Expertise, um Mode zu kreieren, die lokal resoniert und internationale Standards erfüllt.",
    about_global_pres_desc_2: "Globale Modetrends werden in innovative, hochwertige Produkte mit viel Liebe zum Detail übersetzt. Unterstützt durch starke Fertigungs- und Beschaffungsnetzwerke werden Mode-Basics und maßgeschneiderte Lösungen geliefert, um den sich entwickelnden Verbraucherbedürfnissen gerecht zu werden.",
    role_designers: "Experten-Designer aus den Studios in UK und Bangladesch",
    role_designers_desc: "Verbindung globaler Ästhetik mit lokaler Kreativität.",
    role_sourcing: "Beschaffungs- und Marketingspezialisten",
    role_sourcing_desc: "Engagiert für ethische und nachhaltige Beschaffung.",
    role_product: "Experten für Produktentwicklung",
    role_product_desc: "Technische Präzision, trendorientierte Vision.",
    role_merch: "Merchandising-Profis",
    role_merch_desc: "Sorgen für fehlerfreie Produktion & Lieferung.",
    role_garment: "Bekleidungs- & Textiltechnologen",
    role_garment_desc: "Bringen Präzision, Leistung & Innovation.",
    role_qa: "Führungskräfte der Qualitätssicherung",
    role_qa_desc: "Einhaltung höchster Standards in jedem Detail.",
    role_compliance: "Compliance- & Nachhaltigkeitsprofis",
    role_compliance_desc: "Antreiben ethischer, zukunftsfähiger Mode.",
    role_logistics: "Versand- und Logistikspezialist",
    role_logistics_desc: "Präzisionslogistik, fehlerfreie Lieferung.",

    // About - Mission/Vision
    about_mission: "Mission:",
    about_mission_desc: "Lieferung innovativer, ethischer Modebeschaffung mit außergewöhnlichem Design, Qualität und Fertigung – mit Priorität auf trendorientierter Designkreation, Nachhaltigkeit, Rückverfolgbarkeit und dauerhaften Partnerschaften für gegenseitigen Erfolg und positive Wirkung.",
    about_vision: "Vision:",
    about_vision_desc: "ApparelBD strebt an, ein globaler Marktführer in der Bekleidungsbeschaffung zu sein, der neue Standards in Designinnovation, Kundenunterstützung und ethischer Beschaffung setzt und gleichzeitig Kreativität, Nachhaltigkeit und Rückverfolgbarkeit fördert, um dauerhaften Wert zu liefern.",
    about_services_sub: "Was wir tun...",
    
    // About - Values
    about_values_title: "Werte und Beschaffungsphilosophie",
    val_customer_title: "Kundenzentrierung",
    val_customer_desc: "Unsere Kunden stehen im Mittelpunkt unseres Handelns. Wir hören auf ihre Bedürfnisse und streben nach Zufriedenheit durch proaktives Engagement und überlegenen Service.",
    val_integrity_title: "Integrität und Ethik",
    val_integrity_desc: "Wir verpflichten uns zu Vertrauen, Integrität und Ethik in allen Interaktionen, wahren hohe Standards der Ehrlichkeit und fördern Transparenz.",
    val_transparency_title: "Transparenz, Rechenschaftspflicht und Vertrauen",
    val_transparency_desc: "Wir priorisieren Transparenz, Rechenschaftspflicht und Vertrauen, um offene Kommunikation und dauerhafte Partnerschaften auf der Grundlage gegenseitigen Respekts zu fördern.",
    val_price_title: "Wettbewerbsfähiger Preis und Flexibilität",
    val_price_desc: "Wir liefern Premium-Kleidung zu wettbewerbsfähigen Preisen ohne Kompromisse bei der Qualität und gewährleisten außergewöhnliche Handwerkskunst und Haltbarkeit durch strenge Qualitätssicherung.",
    val_quality_title: "Qualität",
    val_quality_desc: "Wir glauben, dass Menschen den Unterschied machen. Unser Team ist zentral für unseren Erfolg und zeigt außergewöhnliche Fähigkeiten. Wir respektieren jeden Einzelnen und schätzen seine Beiträge.",
    val_safety_title: "Sicherheit, Schutz und Arbeitsumgebung",
    val_safety_desc: "Sicherheit und Schutz sind Prioritäten, unterstützt durch strenge Protokolle. Wir fördern Teamarbeit und priorisieren ethische Beschaffung, das Wohlbefinden der Arbeitnehmer und Nachhaltigkeit.",
    val_improvement_title: "Streben nach kontinuierlicher Verbesserung und Exzellenz",
    val_improvement_desc: "Wir leben eine Kultur der Hingabe an kontinuierliche Exzellenz und Verbesserung, verpflichtet, Erwartungen in allen Operationen zu übertreffen.",
    val_innovation_title: "Innovation, Kreativität und Marktintelligenz",
    val_innovation_desc: "Wir konzentrieren uns auf Innovation in Design und Stoff, nutzen Marktforschung, um Trends vorherzusagen und Kundenanforderungen zu erfüllen, und setzen neue Maßstäbe in der Modeindustrie.",
    val_social_title: "Soziale Verantwortung",
    val_social_desc: "Wir priorisieren soziale Verantwortung und Nachhaltigkeit durch ethische Arbeitspraktiken, faire Löhne, Gemeindeentwicklung und nachhaltige Beschaffung.",
    
    about_collab_title: "Wir sind sehr daran interessiert und freuen uns darauf, mit Ihnen zusammenzuarbeiten und zu kooperieren, um überlegene Beschaffungslösungen anzubieten und unsere Fähigkeiten zu verbessern!!",
    about_collab_sub: "Wir warten darauf, Ihr Partner zu sein, also lassen Sie uns zusammenarbeiten...!!!",

