    // Products Page
    prod_hero_title: "Unsere Produktlinien",
    prod_hero_subtitle: "Diversifizierte, hochwertige und breit gefächerte Produktkategorien",
    prod_cat_title: "Produktkategorien",
    prod_intro: "Entdecken Sie unser umfangreiches Sortiment an hochwertiger Bekleidung. Jede Kategorie repräsentiert unser Engagement für Exzellenz, Innovation und vielfältige Modebedürfnisse.",
    prod_drag_hint: "(Ziehen Sie die Galerien nach links oder rechts, um zu erkunden)",
    prod_desc_home: "Am Schnittpunkt von Innovation und Stil bieten wir eine umfangreiche Produktpalette, um vielfältige Modevorlieben zu erfüllen und zeitlose Eleganz mit den neuesten Trends zu verbinden.",
    prod_desc_home_2: "Unsere Mission ist es, Ihre Beschaffungslieferkette vom Design bis zur Lieferung zu verbessern. Mit einem Fokus auf 12 verschiedene Kategorien passen wir Beschaffungslösungen an, um Ihre Bedürfnisse effektiv zu erfüllen.",
    prod_custom_sol: "Benötigen Sie eine maßgeschneiderte Beschaffungslösung?",
    
    // Market Intel Page
    mi_hero_title: "Marktinformationen Design",
    mi_hero_sub: "Design-Expedition",
    mi_fe_title: "MODE-EVOLUTION",
    mi_fe_sub: "Stil in Bewegung neu definieren, wo die Zukunft uns trägt !!",
    mi_fe_text: "Mode-Evolution ist nicht nur eine Bewegung – es ist eine Metamorphose. Ein Reich, in dem Fantasie mit Wissenschaft tanzt und jede Silhouette eine Geschichte von morgen erzählt. Hier konvergieren visionäres Design, furchtlose Forschung und grenzenlose Innovation, um Mode für eine Welt in Bewegung neu zu interpretieren.",
    mi_lang_title: "Mode ist nicht mehr nur Stoff – sie ist eine Sprache!!",
    mi_lang_p1: "Ein lebendiges Spiegelbild sich wandelnder Identitäten, ein mit Werten gewebter Wandteppich, in dem sich alte Fäden mit zukünftigen Formen verflechten.",
    mi_lang_p2: "Bei ApparelBD liegt Evolution in unserer DNA. Unsere Designer verbinden Ethik mit Eleganz, Tradition mit Technologie und fertigen zeitlose, zukunftsweisende Stücke. Mit Materialien der nächsten Generation und Zero-Waste-Design schaffen wir eine neue Ära, in der Stil auf Nachhaltigkeit trifft.",
    mi_lang_footer: "Bedeutungsvoll, faszinierend, bewusst gemacht!!",
    mi_quote_1: "“ Mode bewegt sich mit der Geschwindigkeit der Gedanken und fließt mit dem Geist – Evolution ist ihre Essenz.”",
    mi_rd_title: "Forschung & Entwicklung und Innovation",
    mi_rd_sub: "“Stil innovieren. Wandel inspirieren..”",
    mi_rd_desc: "Bei der Mode-Evolution verschmelzen wir hochmoderne F&E mit kreativer Innovation, um Mode neu zu definieren – wir fertigen langlebige, künstlerische Stücke durch fortschrittliche Stoffe, Verzierungen und Waschtechniken.",
    mi_rd_desc_2: "“Schnelle Mustererstellung und Designverfeinerung werden durch unseren agilen Prozess durch enge Zusammenarbeit und laufende Experimente ermöglicht, wobei erstklassige Qualität und Komfort durch Experten-Fitting und technische Unterstützung gewährleistet werden.”",
    mi_vision_precision: "“Wo Vision auf Präzision trifft.”",
    mi_shaping_future: "Wir passen uns nicht nur der Zukunft der Mode an – wir gestalten sie.",
    mi_design_title: "Designinnovation, kreative Eleganz erheben-",
    mi_design_expedition: "Willkommen bei unserer Design-Expedition-",
    mi_design_exp_desc: "Dies ist mehr als Mode – es ist eine Bewegung. Ein kühnes Engagement, kreative Grenzen zu überschreiten, verantwortungsvolles Design anzunehmen und globalen Wandel zu entfachen. Ob Sie ein neues Label gründen, Ihre Marke neu definieren oder einen Designpartner suchen, um Ihre Vision zum Leben zu erwecken, ApparelBD ist Ihr kreativer Verbündeter.",
    mi_co_creation: "Co-Kreation ist der Kern unseres Prozesses. Durch die Zusammenarbeit mit vielfältigen Designtalenten verschmelzen wir Kreativität mit Markteinblick – und verstärken die Fähigkeiten unserer Kunden, während wir die Markenauthentizität bewahren.",
    mi_crafting_future: "Die Zukunft der Mode gestalten – Stil erheben.... Eleganz neu definieren...!!",
    mi_join_us: "Schließen Sie sich uns an-",
    mi_join_us_desc: "Wo Innovation gedeiht und Mode neu definiert wird.",
    mi_spark_creativity: "Lassen Sie uns Kreativität entfachen, Wandel inspirieren und die Zukunft gemeinsam gestalten!!",
    mi_trend_title: "Trendanalyse: Einsicht-getriebenes Design-",
    mi_trend_1: "Mode entwickelt sich schnell, und vorne zu bleiben erfordert strategischen Einblick.",
    mi_trend_2: "Globale Trendprognose, wir sagen aufkommende Trends weltweit voraus.",
    mi_trend_3: "Saisonale Farb- & Silhouetten-Einblicke, präzise Vorhersagen für die Farben und Formen der Saison.",
    mi_trend_4: "Analyse des Verbraucherverhaltens, wir verfolgen sich ändernde Verbraucherpräferenzen.",
    mi_trend_5: "Wettbewerbs-Benchmarking, Erkenntnisse, um Ihre Marke der Konkurrenz voraus zu halten.",
    mi_insight_quote: "“Bleiben Sie vorne mit einsicht-getriebenem Design, das die Mode von morgen heute gestaltet.”",
    mi_studio_title: "DESIGNSTUDIO:",
    mi_studio_sub: "Wo globale Ideen zu ikonischer Mode werden",
    mi_studio_desc: "Bei ApparelBD ist Design mehr als ein Prozess – es ist eine kontinentübergreifende Zusammenarbeit. Unsere Studios in London und Dhaka arbeiten harmonisch zusammen, um Erkenntnisse, Handwerkskunst und Kreativität in zukunftsfähige, ethisch hergestellte Modekollektionen zu verwandeln. Zusammen bilden sie ein Design-Ökosystem, in dem Ideen sich entwickeln, Ästhetik verfeinert wird und Nachhaltigkeit jeden Schritt leitet.",
    mi_london_title: "ApparelBD London, UK Designstudio:",
    mi_london_leading: "Führend mit Einblick, Eleganz. Kreativität...!!",
    mi_london_desc_long: "Im Herzen Großbritanniens gelegen, führt unser Londoner Studio mit einer einzigartigen Mischung aus Marktintelligenz, Designinnovation, kultureller Geläufigkeit und zeitloser Ästhetik. Wir entwerfen Kollektionen, die inspirieren, die Essenz Ihrer Marke widerspiegeln und neue Trends setzen.",
    mi_uk_designers_desc: "Angetrieben von in Großbritannien geborenen Designern mit globaler Erfahrung bei renommierten Modemarken, verbindet unser Team kreative Vision mit kommerzieller Strategie, um aufschlussreiche, markante und nachhaltige Designs zu liefern. Durch kollaborative Co-Kreation verstärken wir die Stimme Ihrer Marke mit globaler Relevanz – partnerschaftlich vom Konzept bis zum Endprodukt.",
    mi_build_future: "Lassen Sie uns die Zukunft der Mode gemeinsam bauen!!",
    
    mi_studio_highlight_title: "STUDIO-HIGHLIGHT:",
    mi_sh_trend_title: "Trend-Intelligenz",
    mi_sh_trend_items_1: "-Fortgeschrittene Trendvorausschau",
    mi_sh_trend_items_2: "-Kulturelle Geläufigkeit",
    mi_sh_timeless_title: "Zeitloses Design",
    mi_sh_timeless_items_1: "-Ethische Eleganz",
    mi_sh_timeless_items_2: "-Erhabenes, bewusstes Design",
    mi_sh_brand_title: "Markensynergie",
    mi_sh_brand_items_1: "-Markenzentrierte Innovation",
    mi_sh_brand_items_2: "-Weltweiter Markenfokus",
    mi_sh_co_title: "Co-Kreation",
