    mi_dhaka_title: "ApparelBD Dhaka, Bangladesch Designstudio:",
    mi_dhaka_sub: "Die Zukunft fertigen: Erbe, Vision und skalierbares Design!!",
    mi_dhaka_text: "In Dhaka, Bangladesch – einer Stadt, die für ihr reiches Textilerbe bekannt ist – bringt unser Studio traditionelles Handwerkskunst mit modernstem globalen Design zusammen. Hier gründet Kreativität in kultureller Tiefe und wird durch enge Integration mit unserem Londoner Team verstärkt.",
    mi_dhaka_list_1: "-Agiles Design, globale Standards",
    mi_dhaka_list_2: "-Skalierbare Lösungen mit lokaler Expertise",
    mi_dhaka_list_3: "-Authentische Kollektionen, weltweite Wirkung",
    mi_dhaka_list_4: "-Vom Konzept zur Kollektion",
