    mi_from_dhaka_title: "Aus Dhaka,",
    mi_from_dhaka_text: "Kulturelles Erbe trifft moderne Mode, mit Präzision gefertigt, mit Zweck geliefert.",
    mi_from_dhaka_quote: "“Die Seele des Erbes, Mode mit Sorgfalt neu definiert.",
    
    mi_approaches_title: "ApparelBD Ansätze-",
    mi_app_1_title: "-Innovation und Kreativität", mi_app_1_desc: "Treiben jeden Schritt unseres Designprozesses an.",
    mi_app_2_title: "-Markteinblick & kulturelles Bewusstsein", mi_app_2_desc: "Verankert in globalen Trends und Verbraucherverhalten",
