    home_about_subtitle: "Quiénes Somos... !!",
    home_about_text: "En ApparelBD, creemos que la moda no se trata solo de Ropa, es una declaración en constante evolución, una expresión de Identidad. Contexto cultural de tiempo y lugar, percepción, aspiración, creatividad e innovación, valor y creencia del individuo y la comunidad. Impulsamos la moda a través de la inteligencia de mercado, análisis de tendencias, diseño innovador y abastecimiento ético. Respaldados por una sólida garantía de calidad, logística confiable y servicio excepcional, nuestro objetivo es ofrecer un valor sobresaliente a nuestros clientes.",
    home_about_quote: "Nuestro compromiso con la progresión de la moda abarca la inteligencia de mercado, el análisis de tendencias, el diseño innovador y la I+D.",
    home_about_section_title: "Impulsados por Tendencias, Abastecimiento Ético, Confiable y Rastreable – Tu Socio de Fabricación de Moda-",
    home_about_section_text: "Colaboramos con fabricantes que cumplen con normas globales para garantizar la trazabilidad, calidad y control de procesos. Nuestros estudios de diseño en Londres y Daca combinan la Creatividad Global con el talento local, enfocándose en I+D, productos impulsados por tendencias y personajes con licencia icónicos como Disney y otros. Las inspecciones in situ y el soporte logístico completo destacan nuestro compromiso con la fabricación responsable e innovadora.",
    home_about_value_prop: "\"Abastecimiento ético, sostenibilidad, excelencia en fabricación y servicio superior - ofrecen valor añadido al Cliente.\"",
    all_about_us_title: "Todo Sobre Nosotros",
    all_about_us_desc: "Creemos que la Moda no se trata solo de Ropa, es una declaración en constante evolución, una expresión de Identidad, Contexto cultural de tiempo y lugar, percepción, aspiración, creatividad e innovación, valor y creencia del individuo y la comunidad.",
    home_fashion_title: "Evolución de la Moda",
