    home_fashion_text: "Embárcate en el viaje de la Evolución de la Moda — donde el diseño vanguardista y la tecnología de punta dan forma al futuro del estilo. En ApparelBD, la moda habla el lenguaje de las identidades cambiantes, donde la imaginación se encuentra con la ciencia y la tradición se mezcla con la innovación.",
    home_fashion_quote_parallax: "\"La moda no es estática; es una forma de arte en constante evolución. Para mantenernos a la vanguardia, debemos abrazar el cambio y la innovación.\"",
