    about_welcome: "¡Bienvenido a ApparelBD, Donde la Moda se Encuentra con la Integridad!",
    about_intro_title: "¡Socio de Abastecimiento Global Confiable, Estratégico, Sostenible y Ético!",
    about_intro_p1: "Creemos que la Moda no se trata solo de Ropa, es una declaración en constante evolución, una expresión de Identidad, Contexto cultural de tiempo y lugar, percepción, aspiración, creatividad e innovación, valor y creencia del individuo y la comunidad. Fundada en 2024, combinamos creatividad, sostenibilidad y excelencia en fabricación para ofrecer soluciones innovadoras de abastecimiento global.",
    about_intro_p2: "Impulsamos la evolución de la moda a través de inteligencia de mercado, análisis de tendencias, diseño innovador y categorías de productos versátiles. Nuestro compromiso abarca el abastecimiento ético, sostenibilidad, responsabilidad social y cumplimiento internacional. Con socios de fabricación de confianza, garantía de calidad, producción de personajes con licencia y logística integral, ofrecemos un servicio superior y un valor excepcional al cliente.",
