    // About - People
    about_people: "NUESTRA GENTE:",
    about_people_sub: "Nuestra Gente, Nuestra Fuerza: ¡La Experiencia que Nos Impulsa..!!",
    about_people_desc: "En ApparelBD, la moda con propósito es impulsada por personas apasionadas. Nuestra mayor fortaleza es nuestro equipo diverso y conectado globalmente—innovadores que impulsan cada etapa del ciclo de vida de la moda. Desde el diseño de vanguardia y el abastecimiento ético hasta el desarrollo preciso de productos, una rigurosa garantía de calidad y una logística perfecta, nuestros expertos lideran con creatividad, integridad y un compromiso con la sostenibilidad.",
    about_people_desc_2: "La colaboración es nuestra base. Juntos, entregamos soluciones que combinan arte, ética y excelencia—asegurando que cada pieza que creamos tenga un propósito.",
    about_global_pres_title: "Presencia Global, Visión Local",
    about_global_pres_desc: "Con sede en Daca, con estudios de diseño en Daca y Londres, y oficinas de abastecimiento en el Reino Unido, Alemania, Canadá y Nueva Zelanda, fusionamos tendencias globales con experiencia regional para crear moda que resuene localmente y cumpla con los estándares internacionales.",
    about_global_pres_desc_2: "Las tendencias globales de la moda se traducen en productos innovadores y de alta calidad con gran atención al detalle. Con el respaldo de sólidas redes de fabricación y abastecimiento, se entregan elementos esenciales de la moda y soluciones a medida para satisfacer las necesidades cambiantes de los consumidores.",
