    about_mission_desc: "Entregar un abastecimiento de moda innovador y ético con un diseño, calidad y fabricación excepcionales—priorizando la creación de diseños impulsados por tendencias, sostenibilidad, trazabilidad y asociaciones duraderas para el éxito mutuo y un impacto positivo.",
    about_vision: "Visión:",
    about_vision_desc: "ApparelBD tiene como objetivo ser un líder global en el abastecimiento de ropa, estableciendo nuevos estándares en innovación de diseño, atención al cliente y abastecimiento ético, mientras promueve la creatividad, la sostenibilidad y la trazabilidad para ofrecer un valor duradero.",
    about_services_sub: "Lo Que Hacemos...",
    
    // About - Values
    about_values_title: "Valores y Filosofía de Abastecimiento",
    val_customer_title: "Centrado en el Cliente",
    val_customer_desc: "Nuestros clientes están en el corazón de todo lo que hacemos. Escuchamos sus necesidades y buscamos la satisfacción a través de un compromiso proactivo y un servicio superior.",
    val_integrity_title: "Integridad y Ética",
    val_integrity_desc: "Estamos comprometidos con la confianza, la integridad y la ética en todas las interacciones, manteniendo altos estándares de honestidad y promoviendo la transparencia.",
    val_transparency_title: "Transparencia, Responsabilidad y Confianza",
    val_transparency_desc: "Priorizamos la transparencia, la responsabilidad y la confianza para fomentar una comunicación abierta y asociaciones duraderas basadas en el respeto mutuo.",
    val_price_title: "Precio Competitivo y Flexibilidad",
    val_price_desc: "Entregamos ropa premium a precios competitivos sin comprometer la calidad, asegurando una artesanía excepcional y durabilidad a través de una rigurosa garantía de calidad.",
    val_quality_title: "Calidad",
    val_quality_desc: "Creemos que las personas marcan la diferencia. Nuestro equipo es fundamental para nuestro éxito, mostrando capacidades excepcionales. Respetamos a cada individuo y valoramos sus contribuciones.",
    val_safety_title: "Seguridad, Protección y Entorno Laboral",
    val_safety_desc: "La seguridad y la protección son prioridades, respaldadas por protocolos estrictos. Promovemos el trabajo en equipo y priorizamos el abastecimiento ético, el bienestar de los trabajadores y la sostenibilidad.",
    val_improvement_title: "Esfuerzo por la mejora continua y la excelencia",
    val_improvement_desc: "Abrazamos una cultura de dedicación a la excelencia y mejora continua, comprometidos a superar las expectativas en todas las operaciones.",
    val_innovation_title: "Innovación, Creatividad e Inteligencia de Mercado",
    val_innovation_desc: "Nos enfocamos en la innovación en diseño y telas, utilizando la investigación de mercado para pronosticar tendencias y satisfacer las demandas de los clientes, estableciendo nuevos puntos de referencia en la industria de la moda.",
    val_social_title: "Responsabilidad Social",
    val_social_desc: "Priorizamos la responsabilidad social y la sostenibilidad a través de prácticas laborales éticas, salarios justos, desarrollo comunitario y abastecimiento sostenible.",
    
    about_collab_title: "¡Estamos muy interesados y anticipamos ansiosamente asociarnos y colaborar contigo para proporcionar soluciones de abastecimiento superiores y mejorar nuestras capacidades!",
    about_collab_sub: "Estamos esperando ser socios contigo, así que ¡Colaboremos...!!!",

