    // Products Page
    prod_hero_title: "Nuestras Líneas de Productos",
    prod_hero_subtitle: "Categorías de Productos Diversificadas, de Alta Calidad y Amplias",
    prod_cat_title: "Categorías de Productos",
    prod_intro: "Descubre nuestra amplia gama de ropa de alta calidad. Cada categoría representa nuestro compromiso con la excelencia, la innovación y las diversas necesidades de la moda.",
    prod_drag_hint: "(Arrastra las galerías hacia la izquierda o derecha para explorar)",
    prod_desc_home: "En la encrucijada de la innovación y el estilo, ofrecemos una amplia gama de productos para satisfacer diversas preferencias de moda, combinando elegancia atemporal con las últimas tendencias.",
    prod_desc_home_2: "Nuestra misión es mejorar tu cadena de suministro de abastecimiento desde el diseño hasta la entrega. Con un enfoque en 12 categorías distintas, adaptamos soluciones de abastecimiento para satisfacer tus necesidades de manera efectiva.",
    prod_custom_sol: "¿Necesitas una solución de abastecimiento personalizada?",
    
    // Market Intel Page
    mi_hero_title: "Diseño Inteligencia de Mercado",
    mi_hero_sub: "Expedición de Diseño",
    mi_fe_title: "EVOLUCIÓN DE LA MODA",
    mi_fe_sub: "Redefiniendo el Estilo en Movimiento, ¡Donde el Futuro Nos Viste!",
    mi_fe_text: "La Evolución de la Moda no es solo un movimiento—es una metamorfosis. Un reino donde la imaginación baila con la ciencia, y cada silueta cuenta una historia del mañana. Aquí, el diseño visionario, la investigación intrépida y la innovación ilimitada convergen para reimaginar la moda para un mundo en movimiento.",
    mi_lang_title: "La moda ya no es solo tela— ¡es un Lenguaje!",
    mi_lang_p1: "Un reflejo vivo de identidades cambiantes, un tapiz tejido con valores, donde hilos antiguos se entrelazan con formas futuras.",
    mi_lang_p2: "En ApparelBD, la evolución está en nuestro ADN. Nuestros diseñadores mezclan ética con elegancia, tradición con tecnología, elaborando piezas atemporales y orientadas al futuro. Usando materiales de próxima generación y diseño de cero residuos, creamos una nueva era donde el estilo se encuentra con la sostenibilidad.",
    mi_lang_footer: "¡Significativo, Fascinante, Hecho con Conciencia!",
    mi_quote_1: "“ La moda se mueve a la velocidad del pensamiento y fluye con la mente —La Evolución es su Esencia.”",
    mi_rd_title: "Investigación y Desarrollo e Innovación",
    mi_rd_sub: "“Innovando Estilo. Inspirando Cambio..”",
    mi_rd_desc: "En Evolución de la Moda, fusionamos I+D de vanguardia con innovación creativa para redefinir la moda—elaborando piezas duraderas y artísticas a través de telas avanzadas, adornos y técnicas de lavado.",
    mi_rd_desc_2: "“El muestreo rápido y el refinamiento del diseño son posibles gracias a nuestro proceso ágil a través de una estrecha colaboración y experimentación continua, con calidad y comodidad de primer nivel aseguradas por ajuste experto y soporte técnico.”",
    mi_vision_precision: "“Donde la Visión se Encuentra con la Precisión.”",
    mi_shaping_future: "No solo nos adaptamos al futuro de la moda —lo estamos moldeando.",
    mi_design_title: "Innovación en Diseño, Elevando la Elegancia Creativa-",
    mi_design_expedition: "Bienvenido a Nuestra Expedición de Diseño-",
    mi_design_exp_desc: "Esto es más que moda—es un movimiento. Un compromiso audaz para empujar los límites creativos, abrazar el diseño responsable y encender el cambio global. Ya sea que estés lanzando una nueva etiqueta, redefiniendo tu marca o buscando un socio de diseño para dar vida a tu visión, ApparelBD es tu aliado creativo.",
    mi_co_creation: "La co-creación es fundamental en nuestro proceso. Al colaborar con diversos talentos de diseño, fusionamos la creatividad con la visión del mercado—amplificando las capacidades de nuestros clientes mientras preservamos la autenticidad de la marca.",
    mi_crafting_future: "Elaborando el Futuro de la Moda- Elevando el Estilo.... Redefiniendo la Elegancia...!!",
    mi_join_us: "Únete a nosotros-",
    mi_join_us_desc: "Donde la innovación prospera y la moda se redefine.",
    mi_spark_creativity: "¡Encendamos la creatividad, inspiremos el cambio y demos forma al futuro juntos!",
    mi_trend_title: "Análisis de Tendencias: Diseño Impulsado por Perspectivas-",
    mi_trend_1: "La moda evoluciona rápidamente, y mantenerse a la vanguardia requiere una visión estratégica.",
    mi_trend_2: "Pronóstico de Tendencias Globales, Predecimos tendencias emergentes en todo el mundo.",
    mi_trend_3: "Perspectivas Estacionales de Color y Silueta, Predicciones precisas para los colores y formas de la temporada.",
    mi_trend_4: "Análisis del Comportamiento del Consumidor, Rastreamos las preferencias cambiantes de los consumidores.",
    mi_trend_5: "Evaluación Comparativa Competitiva, Perspectivas para mantener tu marca por delante de la competencia.",
    mi_insight_quote: "“Mantente Adelante con Diseño Impulsado por Perspectivas, Dando Forma a la Moda del Mañana Hoy.”",
    mi_studio_title: "ESTUDIO DE DISEÑO:",
    mi_studio_sub: "Donde las Ideas Globales se Convierten en Moda Icónica",
    mi_studio_desc: "En ApparelBD, el diseño es más que un proceso — es una colaboración transcontinental. Nuestros estudios de Londres y Daca trabajan en armonía para transformar ideas, artesanía y creatividad en colecciones de moda listas para el futuro y hechas éticamente. Juntos, forman un ecosistema de diseño donde las ideas evolucionan, la estética se refina y la sostenibilidad guía cada paso",
    mi_london_title: "Estudio de Diseño ApparelBD Londres, Reino Unido:",
    mi_london_leading: "Liderando con Visión, Elegancia. Creatividad...!!",
    mi_london_desc_long: "Ubicado en el corazón del Reino Unido, nuestro estudio de Londres lidera con una mezcla única de inteligencia de mercado, innovación de diseño, fluidez cultural y estética atemporal. Elaboramos colecciones que inspiran, reflejan la esencia de tu marca y establecen nuevas tendencias.",
    mi_uk_designers_desc: "Impulsado por diseñadores de origen británico con experiencia global en marcas de moda de renombre, nuestro equipo fusiona visión artística con estrategia comercial para entregar diseños perspicaces, impactantes y sostenibles. A través de la co-creación colaborativa, amplificamos la voz de tu marca con relevancia global—asociándonos desde el concepto hasta el producto final.",
    mi_build_future: "¡Construyamos el futuro de la moda juntos!",
    
    mi_studio_highlight_title: "DESTACADO DEL ESTUDIO:",
