    mi_london_innovation_quote: "“La innovación se encuentra con la elegancia en nuestro centro de Londres — dando forma a tendencias con integridad.”",
    
    mi_dhaka_title: "Estudio de Diseño ApparelBD Daca, Bangladés:",
    mi_dhaka_sub: "Elaborando el Futuro: Patrimonio, Visión y Diseño Escalable!!",
    mi_dhaka_text: "En Daca, Bangladés — una ciudad conocida por su rico patrimonio textil — nuestro estudio reúne la artesanía tradicional con el diseño global de vanguardia. Aquí, la creatividad se basa en la profundidad cultural y se mejora mediante una estrecha integración con nuestro equipo de Londres.",
