    mi_support_title: "Apoyo en Diseño y Co-Creación:",
    mi_support_sub: "Asociación Creativa de Extremo a Extremo",
    mi_support_text: "En ApparelBD, la co-creación es un viaje compartido de innovación. Nos asociamos con marcas para fusionar su identidad con nuestra experiencia en diseño, elaborando colecciones auténticas y listas para el mercado. Al unir diversas perspectivas y visión estratégica, ayudamos a los clientes a liderar la moda con propósito y originalidad.",
    mi_support_list_1: "• El muestreo rápido mantiene tu colección a tiempo.",
