    mi_support_list_4: "• La orientación sostenible apoya la creación impulsada por un propósito.",
    mi_support_list_5: "• Apoyo tanto en el desarrollo de líneas nuevas como existentes.",
    mi_support_list_6: "• Asegurar que cada diseño refleje la visión de la marca",
    mi_support_quote: "“Elaborado Juntos: ¡Socios en Creatividad, Diseñado para Liderar!!",

    mi_phil_title: "Nuestra Filosofía de Diseño",
    mi_phil_sub: "Inteligencia Creativa con Propósito",
    mi_phil_text: "En ApparelBD, el diseño es una fusión de imaginación, estrategia y responsabilidad. Creemos que cada colección debe ser visualmente impactante, éticamente sólida y comercialmente inteligente — construida no solo para ahora, sino para el futuro.",
    mi_approach_built_on: "Nuestro Enfoque Se Basa En-",
    mi_app_built_1: "Fusión Creativa", mi_app_built_1_sub: "Donde la cultura, la tecnología y la historia se encuentran.",
    mi_app_built_2: "Pensamiento Liderado por Tendencias", mi_app_built_2_sub: "Diseños formados por visión global y datos.",
