    // Home Page
    home_hero_title: "Impegnati per l'Evoluzione della Moda attraverso...",
    home_hero_subtitle: "Supporto al Design Market Intel, Innovazione e Novità di Prodotto, Ampia Gamma di Prodotti Versatili",
    home_quote: "Il modo per iniziare è smettere di parlare e iniziare a fare.",
    quote_author: "- Walt Disney",
    stats_global: "Presenza Globale",
    stats_staff: "Personale in Tutto il Mondo",
    stats_rec: "Raccomandato",
    home_about_title: "CHI SIAMO",
    home_about_subtitle: "Chi Siamo... !!",
    home_about_text: "In ApparelBD, crediamo che la moda non riguardi solo l'Abbigliamento, ma sia un'affermazione in continua evoluzione, un'espressione di Identità. Contesto culturale di tempo e luogo, percezione, aspirazione, creatività e innovazione, valore e credo dell'individuo e della comunità. Spingiamo la moda avanti attraverso l'intelligenza di mercato, l'analisi delle tendenze, il design innovativo e l'approvvigionamento etico. Supportati da una forte garanzia di qualità, una logistica affidabile e un servizio eccezionale, miriamo a offrire un valore eccezionale ai nostri clienti.",
    home_about_quote: "Il nostro impegno per la progressione della moda abbraccia l'intelligenza di mercato, l'analisi delle tendenze, il design innovativo e la R&S.",
    home_about_section_title: "Guidati dalle Tendenze, Approvvigionamento Etico, Affidabile e Tracciabile – Il Tuo Partner per la Produzione di Moda-",
    home_about_section_text: "Collaboriamo con produttori conformi a livello globale per garantire tracciabilità, qualità e controllo dei processi. I nostri studi di design a Londra e Dhaka fondono la Creatività Globale con il talento locale, concentrandosi su R&S, prodotti guidati dalle tendenze e personaggi iconici su licenza come Disney e altri. Ispezioni in loco e supporto logistico completo evidenziano il nostro impegno per una produzione responsabile e innovativa.",
    home_about_value_prop: "\"Approvvigionamento etico, sostenibilità, eccellenza manifatturiera e servizio superiore - offrono un valore aggiunto al Cliente.\"",
    all_about_us_title: "Tutto Su Di Noi",
    all_about_us_desc: "Crediamo che la Moda non riguardi solo l'Abbigliamento, ma sia un'affermazione in continua evoluzione, un'espressione di Identità, contesto culturale di tempo e luogo, percezione, aspirazione, creatività e innovazione, valore e credo dell'individuo e della comunità.",
    home_fashion_title: "Evoluzione della Moda",
    home_fashion_subtitle: "Dove Iniziano le Tendenze — Progettare la Moda in Movimento... !!",
    home_fashion_text: "Intraprendi il viaggio dell'Evoluzione della Moda — dove il design all'avanguardia e la tecnologia di punta plasmano il futuro dello stile. In ApparelBD, la moda parla la lingua delle identità mutevoli, dove l'immaginazione incontra la scienza e la tradizione si fonde con l'innovazione.",
    home_fashion_quote_parallax: "\"La moda non è statica; è una forma d'arte in continua evoluzione. Per rimanere avanti, dobbiamo abbracciare il cambiamento e l'innovazione.\"",
    eth_banner_text: "I nostri partner sono conformi agli standard sociali e ambientali internazionali per proteggere sia le Persone che il Pianeta.",
    earth_quote: "\"La Terra non appartiene a noi, noi apparteniamo alla Terra!\"",
