    // About Page
    about_hero_title: "CHI SIAMO",
    about_hero_sub: "Chi siamo",
    about_welcome: "Benvenuti in ApparelBD, Dove la Moda Incontra l'Integrità!!",
    about_intro_title: "Partner di Approvvigionamento Globale Affidabile, Strategico, Sostenibile ed Etico!!",
    about_intro_p1: "Crediamo che la Moda non riguardi solo l'Abbigliamento, ma sia un'affermazione in continua evoluzione, un'espressione di Identità, Contesto culturale di tempo e luogo, percezione, aspirazione, creatività e innovazione, valore e credo dell'individuo e della comunità. Fondata nel 2024, fondiamo creatività, sostenibilità ed eccellenza manifatturiera per offrire soluzioni innovative di approvvigionamento globale.",
    about_intro_p2: "Guidiamo l'evoluzione della moda attraverso l'intelligenza di mercato, l'analisi delle tendenze, il design innovativo e categorie di prodotti versatili. Il nostro impegno abbraccia l'approvvigionamento etico, la sostenibilità, la responsabilità sociale e la conformità internazionale. Con partner di produzione fidati, garanzia di qualità, produzione di personaggi su licenza e logistica end-to-end, offriamo un servizio superiore e un valore eccezionale per il cliente.",
    about_banner_green: "\"Elevare l'Approvvigionamento, Rafforzare la Partnership- Insieme Otteniamo di Più!!\"",
