    about_ds_dhaka: "Studio di Design a Dhaka, Bangladesh",
    about_ds_dhaka_desc: "Il nostro studio di Dhaka fonde l'artigianato locale con le tendenze globali, offrendo design innovativi e di alta qualità.",
