    // About - People
    about_people: "LE NOSTRE PERSONE:",
    about_people_sub: "Le Nostre Persone, La Nostra Forza: L'Esperienza che Ci Guida..!!",
    about_people_desc: "In ApparelBD, la moda con uno scopo è guidata da persone appassionate. La nostra più grande forza è il nostro team diversificato e connesso a livello globale—innovatori che alimentano ogni fase del ciclo di vita della moda. Dal design all'avanguardia e all'approvvigionamento etico allo sviluppo preciso del prodotto, alla rigorosa garanzia di qualità e alla logistica impeccabile, i nostri esperti guidano con creatività, integrità e impegno per la sostenibilità.",
    about_people_desc_2: "La collaborazione è la nostra fondazione. Insieme, forniamo soluzioni che fondono arte, etica ed eccellenza—garantendo che ogni pezzo che creiamo abbia uno scopo.",
    about_global_pres_title: "Presenza Globale, Intuizione Locale",
    about_global_pres_desc: "Con sede a Dhaka, con studi di design a Dhaka e Londra, e uffici di approvvigionamento nel Regno Unito, Germania, Canada e Nuova Zelanda, fondiamo le tendenze globali con l'esperienza regionale per creare moda che risuoni localmente e soddisfi gli standard internazionali.",
    about_global_pres_desc_2: "Le tendenze globali della moda vengono tradotte in prodotti innovativi e di alta qualità con grande attenzione ai dettagli. Supportati da forti reti di produzione e approvvigionamento, vengono consegnati elementi essenziali della moda e soluzioni su misura per soddisfare le esigenze in evoluzione dei consumatori.",
    role_designers: "Designer Esperti dagli Studi di Regno Unito e Bangladesh",
    role_designers_desc: "Mescolando estetica globale con creatività locale.",
    role_sourcing: "Specialisti in Approvvigionamento e Marketing",
    role_sourcing_desc: "Dedicati all'approvvigionamento etico e sostenibile.",
    role_product: "Esperti in Sviluppo Prodotto",
    role_product_desc: "Precisione tecnica, visione guidata dalle tendenze.",
    role_merch: "Professionisti del Merchandising",
    role_merch_desc: "Garantiscono una produzione e consegna impeccabili.",
    role_garment: "Tecnologi dell'Abbigliamento e dei Tessuti",
    role_garment_desc: "Portano Precisione, prestazioni & innovazione.",
    role_qa: "Leader della Garanzia di Qualità",
    role_qa_desc: "Mantenere i più alti standard in ogni dettaglio.",
    role_compliance: "Professionisti della Conformità & Sostenibilità",
    role_compliance_desc: "Guidare una moda etica e pronta per il futuro.",
    role_logistics: "Specialista in Spedizioni e Logistica",
    role_logistics_desc: "Logistica di precisione, Consegna impeccabile.",

    // About - Mission/Vision
    about_mission: "Missione:",
    about_mission_desc: "Fornire un approvvigionamento di moda innovativo ed etico con design, qualità e produzione eccezionali—dando priorità alla creazione di design guidata dalle tendenze, sostenibilità, tracciabilità e partnership durature per il successo reciproco e un impatto positivo.",
    about_vision: "Visione:",
    about_vision_desc: "ApparelBD mira a essere un leader globale nell'approvvigionamento di abbigliamento, stabilendo nuovi standard nell'innovazione del design, nel supporto al cliente e nell'approvvigionamento etico, promuovendo al contempo creatività, sostenibilità e tracciabilità per offrire un valore duraturo.",
    about_services_sub: "Cosa Facciamo...",
    
    // About - Values
    about_values_title: "Valori e Filosofia di Approvvigionamento",
    val_customer_title: "Centralità del Cliente",
    val_customer_desc: "I nostri clienti sono al centro di tutto ciò che facciamo. Ascoltiamo le loro esigenze e miriamo alla soddisfazione attraverso un impegno proattivo e un servizio superiore.",
    val_integrity_title: "Integrità ed Etica",
    val_integrity_desc: "Ci impegniamo per la fiducia, l'integrità e l'etica in tutte le interazioni, mantenendo alti standard di onestà e promuovendo la trasparenza.",
    val_transparency_title: "Trasparenza, Responsabilità e Fiducia",
    val_transparency_desc: "Diamo priorità alla trasparenza, alla responsabilità e alla fiducia per favorire una comunicazione aperta e partnership durature basate sul rispetto reciproco.",
    val_price_title: "Prezzo Competitivo e Flessibilità",
    val_price_desc: "Offriamo abbigliamento premium a prezzi competitivi senza compromettere la qualità, garantendo un artigianato eccezionale e una durata attraverso una rigorosa garanzia di qualità.",
    val_quality_title: "Qualità",
    val_quality_desc: "Crediamo che le persone facciano la differenza. Il nostro team è fondamentale per il nostro successo, mostrando capacità eccezionali. Rispettiamo ogni individuo e valorizziamo i loro contributi.",
    val_safety_title: "Sicurezza, Protezione e Ambiente di Lavoro",
    val_safety_desc: "La sicurezza e la protezione sono priorità, supportate da protocolli rigorosi. Promuoviamo il lavoro di squadra e diamo priorità all'approvvigionamento etico, al benessere dei lavoratori e alla sostenibilità.",
    val_improvement_title: "Sforzarsi per il miglioramento continuo e l'eccellenza",
    val_improvement_desc: "Abbracciamo una cultura di dedizione all'eccellenza e al miglioramento continui, impegnati a superare le aspettative in tutte le operazioni.",
    val_innovation_title: "Innovazione, Creatività e Intelligenza di Mercato",
    val_innovation_desc: "Ci concentriamo sull'innovazione nel design e nei tessuti, utilizzando la ricerca di mercato per prevedere le tendenze e soddisfare le richieste dei clienti, stabilendo nuovi parametri nell'industria della moda.",
    val_social_title: "Responsabilità Sociale",
    val_social_desc: "Diamo priorità alla responsabilità sociale e alla sostenibilità attraverso pratiche lavorative etiche, salari equi, sviluppo della comunità e approvvigionamento sostenibile.",
    
    about_collab_title: "Siamo molto desiderosi e anticipiamo con impazienza di collaborare con voi per fornire soluzioni di approvvigionamento superiori e migliorare le nostre capacità!!",
    about_collab_sub: "Stiamo aspettando di essere vostri partner, quindi Collaboriamo...!!!",

