    // Products Page
    prod_hero_title: "Le Nostre Linee di Prodotti",
    prod_hero_subtitle: "Categorie di Prodotti Diversificate, di Alta Qualità e Ampie",
    prod_cat_title: "Categorie di Prodotti",
    prod_intro: "Scopri la nostra vasta gamma di abbigliamento di alta qualità. Ogni categoria rappresenta il nostro impegno per l'eccellenza, l'innovazione e le diverse esigenze di moda.",
    prod_drag_hint: "(Trascina le gallerie a sinistra o a destra per esplorare)",
    prod_desc_home: "Al crocevia di innovazione e stile, offriamo una vasta gamma di prodotti per soddisfare diverse preferenze di moda, fondendo eleganza senza tempo con le ultime tendenze.",
    prod_desc_home_2: "La nostra missione è migliorare la tua catena di approvvigionamento dal design alla consegna. Con un focus su 12 categorie distinte, adattiamo soluzioni di approvvigionamento per soddisfare efficacemente le tue esigenze.",
    prod_custom_sol: "Hai bisogno di una soluzione di approvvigionamento personalizzata?",
    
    // Market Intel Page
    mi_hero_title: "Market Intel Design",
    mi_hero_sub: "Spedizione di Design",
    mi_fe_title: "EVOLUZIONE DELLA MODA",
    mi_fe_sub: "Ridefinire lo Stile in Movimento, Dove il Futuro Ci Indossa !!",
    mi_fe_text: "L'Evoluzione della Moda non è solo un movimento—è una metamorfosi. Un regno dove l'immaginazione danza con la scienza, e ogni silhouette racconta una storia di domani. Qui, design visionario, ricerca impavida e innovazione illimitata convergono per reimmaginare la moda per un mondo in movimento.",
    mi_lang_title: "La moda non è più solo tessuto— è un Linguaggio!!",
    mi_lang_p1: "Un riflesso vivente di identità mutevoli, un arazzo intessuto di valori, dove fili antichi si intrecciano con forme future.",
    mi_lang_p2: "In ApparelBD, l'evoluzione è nel nostro DNA. I nostri designer fondono etica con eleganza, tradizione con tecnologia, realizzando pezzi senza tempo e orientati al futuro. Utilizzando materiali di nuova generazione e design a zero rifiuti, creiamo una nuova era in cui lo stile incontra la sostenibilità.",
    mi_lang_footer: "Significativo, Affascinante, Fatto Consapevolmente!!",
    mi_quote_1: "“ La moda si muove alla velocità del pensiero e scorre con la mente —L'Evoluzione è la sua Essenza.”",
    mi_rd_title: "Ricerca & Sviluppo e Innovazione",
    mi_rd_sub: "“Innovare lo Stile. Ispirare il Cambiamento..”",
    mi_rd_desc: "In Evoluzione della Moda, fondiamo R&S all'avanguardia con innovazione creativa per ridefinire la moda—realizzando pezzi durevoli e artistici attraverso tessuti avanzati, abbellimenti e tecniche di lavaggio.",
    mi_rd_desc_2: "“Campionatura rapida e perfezionamento del design sono resi possibili dal nostro processo agile attraverso una stretta collaborazione e sperimentazione continua, con qualità e comfort di prim'ordine garantiti da un fitting esperto e supporto tecnico.”",
    mi_vision_precision: "“Dove la Visione Incontra la Precisione.”",
    mi_shaping_future: "Non ci stiamo solo adattando al futuro della moda —lo stiamo plasmando.",
    mi_design_title: "Innovazione nel Design, Elevare l'Eleganza Creativa-",
    mi_design_expedition: "Benvenuti nella Nostra Spedizione di Design-",
    mi_design_exp_desc: "Questo è più che moda—è un movimento. Un impegno audace a spingere i confini creativi, abbracciare il design responsabile e accendere il cambiamento globale. Che tu stia lanciando un nuovo marchio, ridefinendo il tuo brand o cercando un partner di design per dare vita alla tua visione, ApparelBD è il tuo alleato creativo.",
    mi_co_creation: "La co-creazione è il cuore del nostro processo. Collaborando con diversi talenti del design, fondiamo creatività con intuizione di mercato—amplificando le capacità dei nostri clienti preservando l'autenticità del marchio.",
    mi_crafting_future: "Plasmare il Futuro della Moda- Elevare lo Stile.... Ridefinire l'Eleganza...!!",
    mi_join_us: "Unisciti a noi-",
    mi_join_us_desc: "Dove l'innovazione prospera e la moda viene ridefinita.",
    mi_spark_creativity: "Accendiamo la creatività, ispiriamo il cambiamento e plasmiamo il futuro insieme!!",
    mi_trend_title: "Analisi delle Tendenze: Design Guidato dall'Intuizione-",
    mi_trend_1: "La moda evolve rapidamente, e rimanere avanti richiede una visione strategica.",
    mi_trend_2: "Previsione delle Tendenze Globali, Prevediamo tendenze emergenti in tutto il mondo.",
    mi_trend_3: "Approfondimenti Stagionali su Colori & Silhouette, Previsioni precise per i colori e le forme della stagione.",
    mi_trend_4: "Analisi del Comportamento dei Consumatori, Tracciamo le mutevoli preferenze dei consumatori.",
    mi_trend_5: "Benchmarking Competitivo, Intuizioni per mantenere il tuo marchio avanti rispetto alla concorrenza.",
    mi_insight_quote: "“Rimani Avanti con Design Guidato dall'Intuizione, Plasmando la Moda di Domani Oggi.”",
    mi_studio_title: "STUDIO DI DESIGN:",
    mi_studio_sub: "Dove le Idee Globali Diventano Moda Iconica",
    mi_studio_desc: "In ApparelBD, il design è più di un processo — è una collaborazione transcontinentale. I nostri studi di Londra e Dhaka lavorano in armonia per trasformare intuizioni, artigianato e creatività in collezioni di moda pronte per il futuro e realizzate eticamente. Insieme, formano un ecosistema di design dove le idee evolvono, l'estetica viene raffinata e la sostenibilità guida ogni passo",
    mi_london_title: "Studio di Design ApparelBD Londra, Regno Unito:",
    mi_london_leading: "Guidare con Intuizione, Eleganza. Creatività...!!",
    mi_london_desc_long: "Situato nel cuore del Regno Unito, il nostro studio di Londra guida con una miscela unica di intelligenza di mercato, innovazione nel design, fluidità culturale ed estetica senza tempo. Realizziamo collezioni che ispirano, riflettono l'essenza del tuo marchio e stabiliscono nuove tendenze.",
    mi_uk_designers_desc: "Guidato da designer nati nel Regno Unito con esperienza globale presso rinomati marchi di moda, il nostro team fonde visione artistica con strategia commerciale per offrire design perspicaci, sorprendenti e sostenibili. Attraverso la co-creazione collaborativa, amplifichiamo la voce del tuo marchio con rilevanza globale—collaborando dal concetto al prodotto finale.",
    mi_build_future: "Costruiamo insieme il futuro della moda!!",
    
    mi_studio_highlight_title: "IN EVIDENZA STUDIO:",
    mi_sh_trend_title: "Intelligenza di Tendenza",
    mi_sh_trend_items_1: "-Previsione avanzata delle tendenze",
    mi_sh_trend_items_2: "-Fluidità culturale",
    mi_sh_timeless_title: "Design Senza Tempo",
