    mi_sh_brand_items_2: "-Focus sul Marchio Mondiale",
    mi_sh_co_title: "Co-Creazione",
    mi_sh_co_items_1: "-Collaborazione Collettiva",
    mi_sh_co_items_2: "-Progettare Insieme",
    mi_london_innovation_quote: "“L'innovazione incontra l'eleganza nel nostro hub di Londra — plasmando tendenze con integrità.”",
    
    mi_dhaka_title: "Studio di Design ApparelBD Dhaka, Bangladesh:",
    mi_dhaka_sub: "Plasmare il Futuro: Patrimonio, Visione e Design Scalabile!!",
    mi_dhaka_text: "A Dhaka, Bangladesh — una città nota per il suo ricco patrimonio tessile — il nostro studio riunisce artigianato tradizionale con design globale all'avanguardia. Qui, la creatività è radicata nella profondità culturale e potenziata da una stretta integrazione con il nostro team di Londra.",
    mi_dhaka_list_1: "-Design Agile, Standard Globali",
    mi_dhaka_list_2: "-Soluzioni Scalabili con Expertise Locale",
    mi_dhaka_list_3: "-Collezioni Autentiche, Impatto Mondiale",
    mi_dhaka_list_4: "-Dal Concetto alla Collezione",
    mi_dhaka_list_5: "-Radicato nella Cultura, Costruito per la Scala",
    mi_dhaka_list_6: "-Progettare con Scopo per un Palcoscenico Globale",
    mi_dhaka_highlights_title: "Punti Salienti dello Studio:",
    mi_dhaka_hl_1: "Artisticità Sintonizzata Globalmente",
    mi_dhaka_hl_2: "Guidato dalle Tendenze – Sviluppo Prodotto",
    mi_dhaka_hl_3: "Innovazione sostenibile",
    mi_dhaka_hl_4: "Connesso Globalmente",
    mi_dhaka_hl_5: "Dal Concetto alla Collezione",
    mi_from_dhaka_title: "Da Dhaka,",
    mi_from_dhaka_text: "Il patrimonio culturale incontra la moda moderna Realizzato con precisione, consegnato con scopo.",
    mi_from_dhaka_quote: "“L'anima del patrimonio, Moda ridefinita con cura.",
    
    mi_approaches_title: "Approcci ApparelBD-",
    mi_app_1_title: "-Innovazione e creatività", mi_app_1_desc: "Guidano ogni fase del nostro processo di design.",
    mi_app_2_title: "-Intuizione di Mercato & Consapevolezza Culturale", mi_app_2_desc: "Radicato nelle tendenze globali e nel comportamento dei consumatori",
