    mfg_trace_p1: "La tracciabilità equa è prioritaria attraverso aggiornamenti trasparenti e in tempo reale condivisi con i clienti in ogni fase del viaggio del prodotto—dall'approvvigionamento delle materie prime ai momenti finali della produzione.",
    mfg_trace_p2: "Pratiche etiche e responsabilità incrollabile sono mantenute in tutta la catena di approvvigionamento.",
